export const blogArticles = {
  'blog.compress-pdf-without-losing-quality.title': 'How to Compress a PDF Without Losing Quality',
  'blog.compress-pdf-without-losing-quality.description': 'Why PDFs get so large and how to shrink them without ruining text or photos, using a free method that runs in your browser and never uploads your file.',
  'blog.compress-pdf-without-losing-quality.excerpt': 'Find out what makes a PDF heavy, which kinds shrink well, and how to cut the size while keeping text sharp and selectable.',
  'blog.compress-pdf-without-losing-quality.imageAlt': 'A large PDF document being squeezed into a much smaller file, illustrated on a teal background',
  'blog.compress-pdf-without-losing-quality.intro.1': 'A PDF that is too big to email, or too slow to upload to a portal with a size limit, is one of the most common small annoyances in office life. The usual advice is to run it through an online compressor, but many of those services upload your document to a server, and the results are often disappointing because nobody explains what is actually making the file large.',
  'blog.compress-pdf-without-losing-quality.intro.2': 'This guide explains where the weight in a PDF comes from, what can and cannot be removed, and how to compress a file in your own browser so that text stays sharp and only the images pay the price.',
  'blog.compress-pdf-without-losing-quality.sum.1': 'Images, not text, make most PDFs large, so only the images need to be compressed.',
  'blog.compress-pdf-without-losing-quality.sum.2': 'Photo-heavy and scanned PDFs shrink well; plain text PDFs have little to remove.',
  'blog.compress-pdf-without-losing-quality.sum.3': 'Start with the Recommended strength and check the result at 100% zoom before you send it.',
  'blog.compress-pdf-without-losing-quality.sum.4': 'Compress once, at the end, because every round of recompression costs a little image quality.',
  'blog.compress-pdf-without-losing-quality.s1.h': 'Why PDF files get so large',
  'blog.compress-pdf-without-losing-quality.s1.p1': 'Most of the weight in a PDF is images. A single phone photo can add several megabytes, a scanned page is a full-page picture, and a document exported from a slide deck may embed the same artwork many times. Text is tiny by comparison: a page of typed text is usually a few kilobytes. Embedded fonts add some weight, but far less than most people expect.',
  'blog.compress-pdf-without-losing-quality.s1.p2': 'That is why the first question is not “which tool should I use?” but “what is inside this file?”. A report with twenty photos behaves very differently from a contract made of typed text.',
  'blog.compress-pdf-without-losing-quality.s2.h': 'Three kinds of PDF, three different results',
  'blog.compress-pdf-without-losing-quality.s2.l1.1': 'Text-heavy PDFs (contracts, invoices, articles) are usually small already. There is little to remove, so do not expect dramatic savings.',
  'blog.compress-pdf-without-losing-quality.s2.l1.2': 'Photo-heavy PDFs (brochures, reports, exported presentations) shrink well, because the images can be recompressed and scaled down while the text is left alone.',
  'blog.compress-pdf-without-losing-quality.s2.l1.3': 'Scanned PDFs, where every page is a picture, are large by nature. They can shrink the most, but only by lowering the quality of those pictures.',
  'blog.compress-pdf-without-losing-quality.s3.h': 'How to compress a PDF in your browser',
  'blog.compress-pdf-without-losing-quality.s3.p1': '<tool_compress_pdf>Compress PDF</tool_compress_pdf> works on your own device, so the file is not uploaded anywhere. The steps are short:',
  'blog.compress-pdf-without-losing-quality.s3.o1.1': 'Open the tool and add your PDF (up to 100 MB). If it is password-protected, unlock it first.',
  'blog.compress-pdf-without-losing-quality.s3.o1.2': 'Keep the standard mode. It recompresses the embedded JPEG images and leaves text, links and fonts as they are.',
  'blog.compress-pdf-without-losing-quality.s3.o1.3': 'Pick a strength: Light keeps images almost unchanged, Recommended balances size and quality, and Strong gives the smallest file with visibly softer images.',
  'blog.compress-pdf-without-losing-quality.s3.o1.4': 'Run the compression, compare the sizes before and after, and download the result.',
  'blog.compress-pdf-without-losing-quality.s3.p2': 'If the file could not be made smaller, the tool tells you so instead of handing back a copy that is no better. That normally means the PDF is mostly text, or its images are already small.',
  'blog.compress-pdf-without-losing-quality.s4.h': 'Choosing the right strength',
  'blog.compress-pdf-without-losing-quality.s4.p1': 'Start with Recommended and judge the result at the size you will actually use it. For a document read on a screen, small losses of photo detail are rarely noticeable. For something you will print, or that has small print inside images, start with Light and compare.',
  'blog.compress-pdf-without-losing-quality.s4.n1': 'Tip: zoom to 100% on a page with a photo before you decide. Compression artefacts that are invisible when the page is fitted to the window can appear when you zoom in.',
  'blog.compress-pdf-without-losing-quality.s5.h': 'When to use Maximum mode, and what it costs',
  'blog.compress-pdf-without-losing-quality.s5.p1': 'Maximum mode renders every page as a picture at a resolution set by the strength you chose and builds a new PDF from those pictures. It gives the smallest files for scans, but it has real costs:',
  'blog.compress-pdf-without-losing-quality.s5.l1.1': 'Text can no longer be selected, copied or searched.',
  'blog.compress-pdf-without-losing-quality.s5.l1.2': 'Links and form fields stop working.',
  'blog.compress-pdf-without-losing-quality.s5.l1.3': 'It is a poor choice for documents that people need to fill in or quote from.',
  'blog.compress-pdf-without-losing-quality.s5.p2': 'If you flatten a scan and later need searchable text again, run <tool_ocr_pdf>OCR PDF</tool_ocr_pdf>. It adds an invisible text layer on top of the pages (English only). Our guide to <post_ocr-scanned-pdf-searchable>making a scanned PDF searchable</post_ocr-scanned-pdf-searchable> explains how.',
  'blog.compress-pdf-without-losing-quality.s6.h': 'Other ways to make a PDF smaller',
  'blog.compress-pdf-without-losing-quality.s6.l1.1': 'Split it. If the recipient only needs some pages, <tool_split_pdf>Split PDF</tool_split_pdf> extracts just those.',
  'blog.compress-pdf-without-losing-quality.s6.l1.2': 'Shrink the pictures before they go into the PDF. Compress or resize photos with <tool_image_compressor>Image Compressor</tool_image_compressor>, then build the file with <tool_images_to_pdf>Images to PDF</tool_images_to_pdf>. Our guide to <post_convert-images-to-pdf>converting images to PDF</post_convert-images-to-pdf> covers the details.',
  'blog.compress-pdf-without-losing-quality.s6.l1.3': 'Prefer JPG over PNG for photographs. PNG is lossless and much larger for photos, and the standard compression mode only recompresses JPEG images.',
  'blog.compress-pdf-without-losing-quality.s6.l1.4': 'Compress once, at the end. When you combine files with <tool_merge_pdf>Merge PDF</tool_merge_pdf>, compress the merged file a single time, because every round of recompression costs a little more image quality.',
  'blog.compress-pdf-without-losing-quality.s7.h': 'How small does it need to be?',
  'blog.compress-pdf-without-losing-quality.s7.p1': 'Most limits you will meet are set by the place that receives the file, not by the PDF format. Many email services cap attachments at roughly 20 to 25 MB in total, and job portals, tax sites, university systems and government forms often allow far less, sometimes only a few megabytes. Read the limit before you start so you can stop compressing as soon as the file fits.',
  'blog.compress-pdf-without-losing-quality.s7.p2': 'If you are close to the limit, remember that an email adds a little overhead to every attachment, so aim a comfortable margin under the number rather than exactly on it. If you are far above it, compression alone may not be enough. Combine it with the other options above: remove pages nobody needs, or send two smaller files instead of one large one.',
  'blog.compress-pdf-without-losing-quality.s8.h': 'Common mistakes to avoid',
  'blog.compress-pdf-without-losing-quality.s8.l1.1': 'Compressing a file that is already compressed. A PDF that has been through a compressor, or exported at low quality, has little left to give, and another pass only adds artefacts.',
  'blog.compress-pdf-without-losing-quality.s8.l1.2': 'Judging quality at the wrong zoom level. A page that looks fine fitted to the window can show blocky photos at 100%.',
  'blog.compress-pdf-without-losing-quality.s8.l1.3': 'Using Maximum mode on a document people must fill in or quote from. It turns pages into pictures, so forms and text selection stop working.',
  'blog.compress-pdf-without-losing-quality.s8.l1.4': 'Forgetting to keep the original. Always save the compressed copy under a new name so you can go back to the full-quality file.',
  'blog.compress-pdf-without-losing-quality.s8.l1.5': 'Expecting a miracle from a text-only PDF. If the file is 200 KB of text, there is nothing worth removing.',
  'blog.compress-pdf-without-losing-quality.s9.h': 'What happens to your file',
  'blog.compress-pdf-without-losing-quality.s9.p1': 'Everything described here runs inside your browser tab. The PDF is read from your device, processed locally and offered back as a download. Nothing is sent to our servers, which is also why very large files depend on your computer’s memory. Close the tab and the file is gone.',
  'blog.compress-pdf-without-losing-quality.s10.h': 'A quick checklist',
  'blog.compress-pdf-without-losing-quality.s10.o1.1': 'Work out what is in the file: photos, scans or plain text.',
  'blog.compress-pdf-without-losing-quality.s10.o1.2': 'Try the standard mode at Recommended first.',
  'blog.compress-pdf-without-losing-quality.s10.o1.3': 'Compare the result at 100% zoom.',
  'blog.compress-pdf-without-losing-quality.s10.o1.4': 'Use Light if quality matters more than size, and Strong if size matters more.',
  'blog.compress-pdf-without-losing-quality.s10.o1.5': 'Use Maximum only for scans, and run OCR afterwards if you need searchable text.',
  'blog.compress-pdf-without-losing-quality.faq.h': 'Frequently asked questions',
  'blog.compress-pdf-without-losing-quality.faq.1.q': 'Does compressing a PDF reduce its quality?',
  'blog.compress-pdf-without-losing-quality.faq.1.a': 'In the standard mode only the images are affected: they lose some detail in exchange for a smaller size. Text and vector graphics are not changed. How much you notice depends on the strength you choose and how closely you zoom in.',
  'blog.compress-pdf-without-losing-quality.faq.2.q': 'Why did my PDF barely get smaller?',
  'blog.compress-pdf-without-losing-quality.faq.2.a': 'PDFs that are mostly text, or whose images are already small, have little to remove. Only embedded JPEG images are recompressed, so a PDF built from PNG images or vector artwork gains little in the standard mode.',
  'blog.compress-pdf-without-losing-quality.faq.3.q': 'Is it safe to compress a confidential PDF this way?',
  'blog.compress-pdf-without-losing-quality.faq.3.a': 'The compression runs in your browser and the file is not uploaded, so it does not leave your device. As with any document, avoid working on it on a shared or public computer.',
  'blog.compress-pdf-without-losing-quality.faq.4.q': 'What is the difference between compressing a PDF and resizing its pages?',
  'blog.compress-pdf-without-losing-quality.faq.4.a': 'Compression changes how the images inside the file are stored. Resizing pages changes the paper size and does not make the pictures lighter. For a smaller file, compression is the tool you want.',
  'blog.compress-pdf-without-losing-quality.faq.5.q': 'Can I compress several PDFs at once?',
  'blog.compress-pdf-without-losing-quality.faq.5.a': 'Compress them one at a time, or merge them first and compress the combined file once. Merging first also avoids paying the quality cost of compression twice.',
  'blog.compress-pdf-without-losing-quality.faq.6.q': 'Will compression remove my bookmarks, links or form fields?',
  'blog.compress-pdf-without-losing-quality.faq.6.a': 'In the standard mode the text, links and fonts are left alone. Maximum mode rebuilds every page as a picture, so links and form fields stop working there.',
  'blog.compress-pdf-without-losing-quality.cta.h': 'Try it yourself',
  'blog.compress-pdf-without-losing-quality.cta.p': 'Open <tool_compress_pdf>Compress PDF</tool_compress_pdf>, or browse all of the <all_pdf>PDF tools</all_pdf>.',
  'blog.convert-images-to-pdf.title': 'How to Convert Images to PDF: JPG, PNG and Mixed Photos',
  'blog.convert-images-to-pdf.description': 'Turn photos, screenshots and scans into one tidy PDF. Choose the page order, page size and margins, keep full image quality, and do it all in your browser.',
  'blog.convert-images-to-pdf.excerpt': 'Combine JPG and PNG images into a single PDF with the page order, size and margins you want, without uploading anything.',
  'blog.convert-images-to-pdf.imageAlt': 'Several photos and screenshots stacking into a single PDF document on a teal background',
  'blog.convert-images-to-pdf.intro.1': 'Forms, receipts, homework, ID copies and product photos often arrive as a pile of image files, while the person asking for them wants one PDF. Converting images to PDF is simple, but a few choices decide whether the result looks professional or sloppy: the order of the pages, the page size, the margins and what happens to image quality along the way.',
  'blog.convert-images-to-pdf.intro.2': 'This guide walks through those choices and shows how to build the PDF in your browser, without installing software and without sending your pictures to a server.',
  'blog.convert-images-to-pdf.sum.1': 'One tool turns JPG, PNG and mixed images into a single PDF, with one image per page.',
  'blog.convert-images-to-pdf.sum.2': 'Choose the page size (A4, Letter or Fit to image), the order and the margins before you create the file.',
  'blog.convert-images-to-pdf.sum.3': 'Photographing paper pages? Scan to PDF adds clean-up that makes text easier to read.',
  'blog.convert-images-to-pdf.sum.4': 'Resize or compress very large photos first, so the PDF stays small enough to send.',
  'blog.convert-images-to-pdf.s1.h': 'Pick the right tool for your images',
  'blog.convert-images-to-pdf.s1.p1': 'There are three converters, and the right one depends on what you have:',
  'blog.convert-images-to-pdf.s1.l1.1': '<tool_jpg_to_pdf>JPG to PDF</tool_jpg_to_pdf> when every file is a JPG. The JPEG data is embedded as it is, without re-compression, so quality does not drop.',
  'blog.convert-images-to-pdf.s1.l1.2': '<tool_png_to_pdf>PNG to PDF</tool_png_to_pdf> for screenshots and graphics. Transparency is kept; transparent areas show the white page behind them.',
  'blog.convert-images-to-pdf.s1.l1.3': '<tool_images_to_pdf>Images to PDF</tool_images_to_pdf> for a mix. JPG and PNG are embedded directly, and WebP, GIF or BMP files are converted to PNG first if your browser can read them.',
  'blog.convert-images-to-pdf.s2.h': 'Step by step',
  'blog.convert-images-to-pdf.s2.o1.1': 'Add your images. You can drop several at once; each image becomes one page.',
  'blog.convert-images-to-pdf.s2.o1.2': 'Put them in order by dragging the rows or using the arrows. The order shown is the page order.',
  'blog.convert-images-to-pdf.s2.o1.3': 'Choose a page size: A4, US Letter, or Fit to image, which sizes each page to its picture.',
  'blog.convert-images-to-pdf.s2.o1.4': 'Set the orientation and margin. Automatic orientation follows each image, and margins range from none to large.',
  'blog.convert-images-to-pdf.s2.o1.5': 'Create the PDF and download it.',
  'blog.convert-images-to-pdf.s3.h': 'A4, Letter or Fit to image?',
  'blog.convert-images-to-pdf.s3.p1': 'Use A4 or US Letter when the PDF will be printed, emailed as a document or uploaded to a portal that expects standard pages. Each image is scaled to fit inside the page, keeps its proportions and is centred, so a wide photo on a portrait page gets bands of white above and below rather than being stretched.',
  'blog.convert-images-to-pdf.s3.p2': 'Choose Fit to image when the pictures are the content: a set of screenshots, a comic, a photo album. Every page takes the size of its image, so nothing is scaled or padded and nothing is cropped.',
  'blog.convert-images-to-pdf.s4.h': 'Getting the order and orientation right',
  'blog.convert-images-to-pdf.s4.p1': 'File names rarely sort the way you want, especially when photos come from a phone, so check the list before creating the PDF. If some pictures are sideways, fix them first with the image tools and add them again. With A4 or Letter, Automatic orientation chooses landscape for wide images and portrait for tall ones, which is usually what you want for a mixed set. Pick a fixed orientation only when every page must match.',
  'blog.convert-images-to-pdf.s4.n1': 'Tip: for documents such as receipts, take the photo straight on, in good light and with the page filling the frame. A cleaner picture gives a cleaner PDF, and a scanned page is far easier to read later with <tool_ocr_pdf>OCR PDF</tool_ocr_pdf>.',
  'blog.convert-images-to-pdf.s5.h': 'Keeping the file size reasonable',
  'blog.convert-images-to-pdf.s5.p1': 'A modern phone photo is often 3 to 8 MB, so twenty of them make a PDF too big for most email limits. Because JPEG data is embedded without re-compression, the PDF is about as large as the pictures combined. Two fixes work well: reduce the pictures before converting with <tool_image_compressor>Image Compressor</tool_image_compressor> or <tool_image_resizer>Image Resizer</tool_image_resizer>, or compress the finished PDF with <tool_compress_pdf>Compress PDF</tool_compress_pdf>. We compare both in <post_compress-pdf-without-losing-quality>how to compress a PDF without losing quality</post_compress-pdf-without-losing-quality>.',
  'blog.convert-images-to-pdf.s6.h': 'After the PDF exists',
  'blog.convert-images-to-pdf.s6.l1.1': 'Need this PDF inside a longer document? Combine them with <tool_merge_pdf>Merge PDF</tool_merge_pdf>.',
  'blog.convert-images-to-pdf.s6.l1.2': 'Only some pages needed? Extract them with <tool_split_pdf>Split PDF</tool_split_pdf>.',
  'blog.convert-images-to-pdf.s6.l1.3': 'Going the other way? <tool_pdf_to_jpg>PDF to JPG</tool_pdf_to_jpg> turns pages back into pictures.',
  'blog.convert-images-to-pdf.s7.h': 'Photographing paper pages: use Scan to PDF',
  'blog.convert-images-to-pdf.s7.p1': 'A photo of a printed page is not the same as a scan. It has uneven light, soft shadows from your hand or the phone, and a slightly grey background, and all of that shows up when someone reads or prints the PDF. <tool_scan_to_pdf>Scan to PDF</tool_scan_to_pdf> is built for that case. You add the page photos, put them in order, and choose a clean-up style: Original keeps the colours, Grayscale removes them, and Black and white document evens out shadows and turns the page into dark text on white paper.',
  'blog.convert-images-to-pdf.s7.p2': 'The black and white mode suits printed pages and handwritten notes. It is not meant for photographs, where it would throw away tone and detail. Scan to PDF does not recognise the text, so the result is still a set of pictures. If you need to search or copy the words, run <tool_ocr_pdf>OCR PDF</tool_ocr_pdf> afterwards, as described in our guide to <post_ocr-scanned-pdf-searchable>making a scanned PDF searchable</post_ocr-scanned-pdf-searchable>.',
  'blog.convert-images-to-pdf.s7.p3': 'On a phone or tablet whose browser supports it, a Take a photo button opens the camera directly. Otherwise choose pictures that are already saved on the device.',
  'blog.convert-images-to-pdf.s8.h': 'Tips for sharper, better-looking pages',
  'blog.convert-images-to-pdf.s8.l1.1': 'Photograph pages in daylight or under an even lamp, with the phone directly above the paper instead of at an angle.',
  'blog.convert-images-to-pdf.s8.l1.2': 'Fill the frame with the page and keep the edges straight; crop out the table around it before building the PDF.',
  'blog.convert-images-to-pdf.s8.l1.3': 'Hold the camera steady or use a timer, because a slightly blurred photo cannot be repaired afterwards.',
  'blog.convert-images-to-pdf.s8.l1.4': 'Use the same orientation for every page. If one page is sideways, rotate the picture first so the PDF opens the right way up.',
  'blog.convert-images-to-pdf.s8.l1.5': 'Name your files in the order you want them, for example page-01, page-02, so the list is already sorted when you add them.',
  'blog.convert-images-to-pdf.s9.h': 'Limits worth knowing',
  'blog.convert-images-to-pdf.s9.l1.1': 'Up to 25 MB per image and 100 images per PDF.',
  'blog.convert-images-to-pdf.s9.l1.2': 'JPG to PDF accepts JPG files only; use Images to PDF for mixed formats.',
  'blog.convert-images-to-pdf.s9.l1.3': 'Everything runs in your browser, so speed and the number of images you can handle depend on your device’s memory.',
  'blog.convert-images-to-pdf.faq.h': 'Frequently asked questions',
  'blog.convert-images-to-pdf.faq.1.q': 'Does converting a JPG to PDF reduce its quality?',
  'blog.convert-images-to-pdf.faq.1.a': 'No. JPG files are embedded in the PDF as they are, without re-compression, so the picture is identical to the original.',
  'blog.convert-images-to-pdf.faq.2.q': 'Can I put different image formats in one PDF?',
  'blog.convert-images-to-pdf.faq.2.a': 'Yes, with Images to PDF. JPG and PNG are embedded directly, and WebP, GIF and BMP files are converted to PNG first if your browser can decode them.',
  'blog.convert-images-to-pdf.faq.3.q': 'What is the difference between Images to PDF and Scan to PDF?',
  'blog.convert-images-to-pdf.faq.3.a': 'Images to PDF places your pictures on pages as they are. Scan to PDF does the same and can also clean up photographed paper pages, for example by evening out shadows and turning them into black and white. Neither tool recognises text.',
  'blog.convert-images-to-pdf.faq.4.q': 'Why does my iPhone photo not appear in the list?',
  'blog.convert-images-to-pdf.faq.4.a': 'Some phone formats, such as HEIC, cannot be read by a browser. Save or export the picture as a JPG first, or change the camera format to the most compatible option, and add it again.',
  'blog.convert-images-to-pdf.faq.5.q': 'How many images can I put in one PDF?',
  'blog.convert-images-to-pdf.faq.5.a': 'Images to PDF handles many pictures in one go, within the size limits shown on the tool page. If you have far more, build several PDFs and join them with Merge PDF.',
  'blog.convert-images-to-pdf.faq.6.q': 'Are my pictures uploaded when I convert them?',
  'blog.convert-images-to-pdf.faq.6.a': 'No. The PDF is built inside your browser from files on your device, and nothing is sent to our servers.',
  'blog.convert-images-to-pdf.cta.h': 'Try it yourself',
  'blog.convert-images-to-pdf.cta.p': 'Open <tool_images_to_pdf>Images to PDF</tool_images_to_pdf>, or browse all of the <all_pdf>PDF tools</all_pdf>.',
  'blog.how-to-format-and-validate-json.title': 'How to Format and Validate JSON: A Practical Guide',
  'blog.how-to-format-and-validate-json.description': 'Learn the rules of valid JSON and the mistakes that break it, then format, validate and minify JSON in your browser with exact line and column errors.',
  'blog.how-to-format-and-validate-json.excerpt': 'Fix broken JSON quickly. See the syntax rules, the most common errors and how to pretty-print, validate and minify JSON.',
  'blog.how-to-format-and-validate-json.imageAlt': 'A block of curly-brace JSON code being aligned into neat indented lines on a teal background',
  'blog.how-to-format-and-validate-json.intro.1': 'An API returns one long line of brackets and quotes. A config file will not load and the error says only “unexpected token”. A colleague pastes a JSON snippet into a chat and it has lost half its structure. JSON is simple, but it is strict, and a single stray character breaks the whole document.',
  'blog.how-to-format-and-validate-json.intro.2': 'This guide covers the rules that matter, the mistakes behind most errors, and a quick workflow for formatting, checking and shrinking JSON in your browser, with nothing uploaded to a server.',
  'blog.how-to-format-and-validate-json.sum.1': 'JSON allows only double-quoted strings and keys, no trailing commas and no comments.',
  'blog.how-to-format-and-validate-json.sum.2': 'A validator tells you the exact line and column of the first error, which is usually enough to fix it.',
  'blog.how-to-format-and-validate-json.sum.3': 'Format (pretty-print) JSON to read it and minify it to send it; neither changes the data.',
  'blog.how-to-format-and-validate-json.sum.4': 'Numbers larger than 2 to the power of 53 lose precision when a browser parses them.',
  'blog.how-to-format-and-validate-json.s1.h': 'What JSON is',
  'blog.how-to-format-and-validate-json.s1.p1': 'JSON, short for JavaScript Object Notation, is a plain-text format for structured data. It has six kinds of value: objects in curly braces, arrays in square brackets, strings, numbers, true or false, and null. Objects hold key and value pairs; arrays hold ordered lists.',
  'blog.how-to-format-and-validate-json.s1.p2': 'Because it is plain text, it works everywhere: web APIs, configuration files, app settings, exports from databases and tools. That portability is why everyone uses it, and why a small mistake in a hand-edited file causes so much trouble.',
  'blog.how-to-format-and-validate-json.s2.h': 'The rules that cause most errors',
  'blog.how-to-format-and-validate-json.s2.p1': 'JSON looks like JavaScript, but its rules are stricter. Almost every “invalid JSON” message traces back to one of these:',
  'blog.how-to-format-and-validate-json.s2.l1.1': 'Keys and strings must use double quotes. Single quotes and unquoted keys are not valid.',
  'blog.how-to-format-and-validate-json.s2.l1.2': 'No trailing commas. A comma after the last item of an object or array breaks the document.',
  'blog.how-to-format-and-validate-json.s2.l1.3': 'No comments. JSON has no comment syntax, so lines starting with // or blocks in slashes and asterisks are errors.',
  'blog.how-to-format-and-validate-json.s2.l1.4': 'Values must be one of the six types. undefined, NaN and Infinity are not valid JSON values.',
  'blog.how-to-format-and-validate-json.s2.l1.5': 'Strings must escape special characters. A quote inside a string needs a backslash, and a raw line break inside a string is not allowed; write it as \\n.',
  'blog.how-to-format-and-validate-json.s2.l1.6': 'Brackets and braces must match. Every opening one needs its closing partner, in the right order.',
  'blog.how-to-format-and-validate-json.s3.h': 'Validate: find the exact problem',
  'blog.how-to-format-and-validate-json.s3.p1': '<tool_json_validator>JSON Validator</tool_json_validator> checks whether your text is valid JSON and, if it is not, points to the exact line and column of the error. Paste the document, read the message and fix it, then check again.',
  'blog.how-to-format-and-validate-json.s3.p2': 'Two tips make this faster:',
  'blog.how-to-format-and-validate-json.s3.l1.1': 'The reported position is where the parser noticed the problem, which can be just after the real mistake. If the line looks fine, check the line above, especially for a missing comma or a missing closing quote.',
  'blog.how-to-format-and-validate-json.s3.l1.2': 'Fix one error at a time. A single missing bracket can produce confusing messages further down, and most of them disappear once the first is fixed.',
  'blog.how-to-format-and-validate-json.s3.p3': 'The validator checks syntax only. It tells you whether the JSON is well-formed, not whether it has the fields your application expects. Checking against a JSON Schema is not included.',
  'blog.how-to-format-and-validate-json.s4.h': 'Format: make it readable',
  'blog.how-to-format-and-validate-json.s4.p1': '<tool_json_formatter>JSON Formatter</tool_json_formatter> adds line breaks and indentation so that nested structures become easy to scan. You can choose the indentation and sort the keys alphabetically.',
  'blog.how-to-format-and-validate-json.s4.o1.1': 'Paste your JSON.',
  'blog.how-to-format-and-validate-json.s4.o1.2': 'Choose the indentation, for example two spaces, and whether to sort keys.',
  'blog.how-to-format-and-validate-json.s4.o1.3': 'Copy the formatted result or download it.',
  'blog.how-to-format-and-validate-json.s4.p2': 'Sorting keys is useful when you want to compare two documents, because the same data then appears in the same order. It changes only the order of keys in objects, not the order of array items, and it does not change any values. If you want to see exactly what differs between two versions, paste both into <tool_text_diff_checker>Text Diff Checker</tool_text_diff_checker> after formatting them the same way.',
  'blog.how-to-format-and-validate-json.s5.h': 'Minify: make it small',
  'blog.how-to-format-and-validate-json.s5.p1': '<tool_json_minifier>JSON Minifier</tool_json_minifier> does the opposite of formatting. It removes all whitespace that is not needed, which makes the text smaller for sending over a network or storing in a field. The data stays exactly the same, so you can format it again at any time.',
  'blog.how-to-format-and-validate-json.s5.p2': 'Use formatted JSON for reading and editing, and minified JSON for sending and storing. Do not try to read minified output by eye; format it first.',
  'blog.how-to-format-and-validate-json.s6.h': 'Large numbers and other surprises',
  'blog.how-to-format-and-validate-json.s6.p1': 'JavaScript, and therefore the browser, stores numbers as 64-bit floating-point values. Integers larger than 2 to the power of 53, about 9 quadrillion, cannot all be represented exactly. If your JSON contains such an id or a very long number, parsing and re-printing it can change the last digits. When ids are that long, treat them as strings in the JSON.',
  'blog.how-to-format-and-validate-json.s6.p2': 'Other things to watch for:',
  'blog.how-to-format-and-validate-json.s6.l1.1': 'Duplicate keys in the same object are allowed by the syntax but unreliable, because programs differ in which value they keep.',
  'blog.how-to-format-and-validate-json.s6.l1.2': 'Dates have no special type in JSON. They are usually strings in a standard format, so their meaning depends on the agreement between sender and receiver.',
  'blog.how-to-format-and-validate-json.s6.l1.3': 'Special characters and non-Latin text are fine. JSON is Unicode text, and the tools handle it correctly.',
  'blog.how-to-format-and-validate-json.s7.h': 'A quick workflow for broken JSON',
  'blog.how-to-format-and-validate-json.s7.o1.1': 'Paste it into the JSON Validator and read the message.',
  'blog.how-to-format-and-validate-json.s7.o1.2': 'Fix the first error, usually a quote, a comma or a bracket.',
  'blog.how-to-format-and-validate-json.s7.o1.3': 'Repeat until the validator reports valid JSON.',
  'blog.how-to-format-and-validate-json.s7.o1.4': 'Format it so you can read the structure.',
  'blog.how-to-format-and-validate-json.s7.o1.5': 'Minify it again if you need the compact version.',
  'blog.how-to-format-and-validate-json.s8.h': 'Related tasks',
  'blog.how-to-format-and-validate-json.s8.p1': 'JSON often travels inside other text. Query-string values and URLs need percent-encoding, which <tool_url_encoder_decoder>URL Encoder / Decoder</tool_url_encoder_decoder> handles, and binary or awkward text is often wrapped in Base64. Our guide to <post_what-is-base64-encoding>what Base64 encoding is</post_what-is-base64-encoding> explains when and why, and <tool_base64_encoder_decoder>Base64 Encoder / Decoder</tool_base64_encoder_decoder> converts it in your browser.',
  'blog.how-to-format-and-validate-json.s9.h': 'Embedded pictures make JSON heavy',
  'blog.how-to-format-and-validate-json.s9.p1': 'Some JSON files carry images as Base64 text. Because Base64 is about a third larger than the original data, a few large pictures can make a file huge. Shrink the pictures before encoding them; our guide to <post_reduce-image-size-in-kb>reducing image size in KB</post_reduce-image-size-in-kb> shows how.',
  'blog.how-to-format-and-validate-json.s10.h': 'Privacy',
  'blog.how-to-format-and-validate-json.s10.p1': 'All three JSON tools run in your browser. What you paste is parsed on your device and is not sent to a server. Even so, avoid pasting live credentials, tokens or personal data into any tool you do not control, and remove them from samples you share.',
  'blog.how-to-format-and-validate-json.faq.h': 'Frequently asked questions',
  'blog.how-to-format-and-validate-json.faq.1.q': 'Why is my JSON invalid when it looks fine?',
  'blog.how-to-format-and-validate-json.faq.1.a': 'The usual causes are single quotes instead of double quotes, a trailing comma, a comment, or an unquoted key. The validator shows the exact line and column of the first error.',
  'blog.how-to-format-and-validate-json.faq.2.q': 'Does formatting JSON change the data?',
  'blog.how-to-format-and-validate-json.faq.2.a': 'No. Formatting only changes whitespace, and sorting changes the order of keys in objects. Values and array order stay the same.',
  'blog.how-to-format-and-validate-json.faq.3.q': 'Can JSON have comments?',
  'blog.how-to-format-and-validate-json.faq.3.a': 'No. Standard JSON has no comment syntax. If a file with comments is accepted by some program, that program supports an extended format, not JSON itself.',
  'blog.how-to-format-and-validate-json.faq.4.q': 'What is the difference between formatting and minifying?',
  'blog.how-to-format-and-validate-json.faq.4.a': 'Formatting adds indentation and line breaks for readability. Minifying removes unneeded whitespace to make the text smaller. The content is identical.',
  'blog.how-to-format-and-validate-json.faq.5.q': 'Is my JSON uploaded when I use these tools?',
  'blog.how-to-format-and-validate-json.faq.5.a': 'No. The tools run in your browser, so the text stays on your device.',
  'blog.how-to-format-and-validate-json.cta.h': 'Format your JSON now',
  'blog.how-to-format-and-validate-json.cta.p': 'Open <tool_json_formatter>JSON Formatter</tool_json_formatter>, or browse all of the <all_developer>developer tools</all_developer>.',
  'blog.how-to-merge-pdf-files.title': 'How to Merge PDF Files Online: Order, Size and Limits',
  'blog.how-to-merge-pdf-files.description': 'Combine several PDFs into one document in the right order, keep the size under control and avoid common problems, all in your browser with no upload.',
  'blog.how-to-merge-pdf-files.excerpt': 'Join contracts, invoices and scans into one PDF in the order you choose, and learn what merging keeps, drops and how to keep the result small.',
  'blog.how-to-merge-pdf-files.imageAlt': 'Three separate PDF pages sliding together into one combined document on a teal background',
  'blog.how-to-merge-pdf-files.intro.1': 'Applications, tax returns, invoices, project reports: sooner or later somebody asks you for “everything in one PDF”. You have the cover letter in one file, the form in another, a scan of an ID in a third, and no wish to send three attachments that might be opened in the wrong order.',
  'blog.how-to-merge-pdf-files.intro.2': 'Merging fixes that. This guide shows how to combine PDFs in your browser, how to get the order right the first time, what merging does not carry over, and how to keep the final file small enough to send.',
  'blog.how-to-merge-pdf-files.sum.1': 'Merge PDF joins two or more PDFs into one document, in the order you set with the arrows.',
  'blog.how-to-merge-pdf-files.sum.2': 'The files are combined on your own device and are not uploaded.',
  'blog.how-to-merge-pdf-files.sum.3': 'Page content and links are kept; bookmarks and form fields of the source files are not.',
  'blog.how-to-merge-pdf-files.sum.4': 'Password-protected PDFs must be unlocked first, and the merged file is best compressed once at the end.',
  'blog.how-to-merge-pdf-files.s1.h': 'When merging is the right move',
  'blog.how-to-merge-pdf-files.s1.p1': 'Merge when the recipient needs a single document to read, print or archive: a job application pack, a set of supporting documents for a visa or loan, the monthly invoices for your accountant, or chapters of a report written by different people. A single PDF opens in one window, prints in one job and cannot lose a page on the way.',
  'blog.how-to-merge-pdf-files.s1.p2': 'Do not merge when the files serve different purposes or will be edited separately. If one part of the pack changes often, keep it as its own file and merge only at the moment you send it.',
  'blog.how-to-merge-pdf-files.s2.h': 'How to merge PDFs in your browser',
  'blog.how-to-merge-pdf-files.s2.p1': '<tool_merge_pdf>Merge PDF</tool_merge_pdf> runs inside your browser tab. Your documents are read from your device, joined locally and offered back as a download.',
  'blog.how-to-merge-pdf-files.s2.o1.1': 'Open the tool and add your PDFs. You can choose several files at once or drag them onto the page. Each file can be up to 100 MB.',
  'blog.how-to-merge-pdf-files.s2.o1.2': 'Put the files in the order you want. Use the arrows to move a file up or down. The list is the order of the final document.',
  'blog.how-to-merge-pdf-files.s2.o1.3': 'Press Merge and wait a moment. Larger files take longer because your own device does the work.',
  'blog.how-to-merge-pdf-files.s2.o1.4': 'Download the combined PDF and open it before you send it.',
  'blog.how-to-merge-pdf-files.s3.h': 'Getting the order right',
  'blog.how-to-merge-pdf-files.s3.p1': 'The most common mistake is not the merge itself but the order. The files are joined exactly as listed, so check the list from top to bottom before you press the button. A few habits help:',
  'blog.how-to-merge-pdf-files.s3.l1.1': 'Name your files so they sort naturally, for example 01-cover-letter, 02-form, 03-id-scan. When the names already carry the order, the list is right from the start.',
  'blog.how-to-merge-pdf-files.s3.l1.2': 'Put the page that explains the pack first. A short cover page or summary makes a long pack much easier to read.',
  'blog.how-to-merge-pdf-files.s3.l1.3': 'Check the page count afterwards. If three files of 2, 4 and 3 pages gave you 9 pages, the merge is complete.',
  'blog.how-to-merge-pdf-files.s3.p2': 'If you need to change the order of individual pages after merging, <tool_reorder_pdf_pages>Reorder PDF Pages</tool_reorder_pdf_pages> shows thumbnails you can drag, and <tool_remove_pdf_pages>Remove PDF Pages</tool_remove_pdf_pages> deletes pages you do not need.',
  'blog.how-to-merge-pdf-files.s4.h': 'What merging keeps and what it does not',
  'blog.how-to-merge-pdf-files.s4.p1': 'Merging copies the visible content of every page: text, images, vector graphics and links. The merged file is a normal PDF that opens in any reader.',
  'blog.how-to-merge-pdf-files.s4.p2': 'Some document-level features do not carry over from the source files:',
  'blog.how-to-merge-pdf-files.s4.l1.1': 'Bookmarks and outlines of the individual files are not merged. The combined file has no table of contents unless you build one elsewhere.',
  'blog.how-to-merge-pdf-files.s4.l1.2': 'Form fields are not merged, so a fillable form will be flattened into what it looks like. If a form must stay fillable, complete it before merging or send it as its own file.',
  'blog.how-to-merge-pdf-files.s4.l1.3': 'Password-protected PDFs are not supported. If one of your files asks for a password, remove it first with <tool_unlock_pdf>Unlock PDF</tool_unlock_pdf>, which works when you know the password.',
  'blog.how-to-merge-pdf-files.s4.n1': 'Tip: merge a copy, not your only version. Keep the originals in a folder so you can rebuild the pack if a page turns out to be missing or in the wrong place.',
  'blog.how-to-merge-pdf-files.s5.h': 'Keep the merged file a sensible size',
  'blog.how-to-merge-pdf-files.s5.p1': 'A merged PDF is as large as the sum of its parts, and attachment limits are set by the receiving system. Many email services accept attachments of roughly 20 to 25 MB in total, and online portals often allow much less.',
  'blog.how-to-merge-pdf-files.s5.p2': 'If the result is too large, reduce it in this order:',
  'blog.how-to-merge-pdf-files.s5.o1.1': 'Remove pages nobody needs, such as blank pages and duplicates.',
  'blog.how-to-merge-pdf-files.s5.o1.2': 'Compress the merged file once with <tool_compress_pdf>Compress PDF</tool_compress_pdf>. Our guide to <post_compress-pdf-without-losing-quality>compressing a PDF without losing quality</post_compress-pdf-without-losing-quality> explains the strengths and what to expect.',
  'blog.how-to-merge-pdf-files.s5.o1.3': 'Compress before you merge only if a single source file is huge, for example a scan with high-resolution photos.',
  'blog.how-to-merge-pdf-files.s5.p3': 'Compressing the combined file once is better than compressing every part, because each round of recompression costs a little image quality.',
  'blog.how-to-merge-pdf-files.s6.h': 'Add page numbers after merging',
  'blog.how-to-merge-pdf-files.s6.p1': 'Each source file starts at page 1 on its own, so a merged pack can have several “page 1” labels printed on its pages. If readers will refer to pages by number, number the whole document after merging with <tool_add_page_numbers>Add Page Numbers</tool_add_page_numbers>, so the numbers run from the first page to the last.',
  'blog.how-to-merge-pdf-files.s7.h': 'Merging scanned documents',
  'blog.how-to-merge-pdf-files.s7.p1': 'Scans merge exactly like any other PDF, but remember two things. They are heavy, so check the size afterwards. And they contain pictures of text, not text, so the merged file will not be searchable. If you need to search it, add a text layer with OCR PDF; our guide to <post_ocr-scanned-pdf-searchable>making a scanned PDF searchable</post_ocr-scanned-pdf-searchable> shows how. If your starting point is a pile of photos, <post_convert-images-to-pdf>convert the images to PDF</post_convert-images-to-pdf> first and then merge the result with the rest.',
  'blog.how-to-merge-pdf-files.s8.h': 'Merging and splitting go together',
  'blog.how-to-merge-pdf-files.s8.p1': 'Merging is half of a pair. If a pack arrives as one large file and you only need parts of it, our guide to <post_how-to-split-a-pdf>splitting a PDF</post_how-to-split-a-pdf> shows how to cut it by range, page or chunk. A common routine is to split a document, replace one part, and merge the parts again.',
  'blog.how-to-merge-pdf-files.s9.h': 'Fixing problems',
  'blog.how-to-merge-pdf-files.s9.l1.1': 'A file will not add: it is probably password-protected, damaged or over 100 MB. Unlock it, split it, or repair it first; our guide to <post_repair-a-corrupted-pdf>repairing a corrupted PDF</post_repair-a-corrupted-pdf> explains what can be recovered.',
  'blog.how-to-merge-pdf-files.s9.l1.2': 'The order is wrong after merging: go back, fix the list order and merge again from your originals. For a small fix, use Reorder PDF Pages.',
  'blog.how-to-merge-pdf-files.s9.l1.3': 'The merged file looks larger than expected: that is normal. Compress it once at the end.',
  'blog.how-to-merge-pdf-files.s9.l1.4': 'A fillable form no longer fills: form fields are not carried over by merging. Complete the form first, then merge.',
  'blog.how-to-merge-pdf-files.faq.h': 'Frequently asked questions',
  'blog.how-to-merge-pdf-files.faq.1.q': 'Is it safe to merge confidential PDFs online?',
  'blog.how-to-merge-pdf-files.faq.1.a': 'Merge PDF runs in your browser, so the files are processed on your device and are not uploaded to a server. As with any sensitive document, avoid doing it on a shared or public computer.',
  'blog.how-to-merge-pdf-files.faq.2.q': 'Is there a limit on how many files I can merge?',
  'blog.how-to-merge-pdf-files.faq.2.a': 'Each file can be up to 100 MB, and the tool limits how many files you can add at once to keep your browser responsive. For a very large pack, merge it in two stages.',
  'blog.how-to-merge-pdf-files.faq.3.q': 'Will merging reduce the quality of my pages?',
  'blog.how-to-merge-pdf-files.faq.3.a': 'No. Pages are copied across without being recompressed, so text and images look the same. Quality only drops if you compress the merged file afterwards.',
  'blog.how-to-merge-pdf-files.faq.4.q': 'Can I merge a PDF with images?',
  'blog.how-to-merge-pdf-files.faq.4.a': 'First turn the images into a PDF with Images to PDF, then merge that PDF with the others. That also lets you choose the page size and margins for the pictures.',
  'blog.how-to-merge-pdf-files.faq.5.q': 'Can I undo a merge?',
  'blog.how-to-merge-pdf-files.faq.5.a': 'Split PDF can separate the combined file again by page ranges, but it is easier to keep your original files and simply merge again if you need a different version.',
  'blog.how-to-merge-pdf-files.cta.h': 'Merge your PDFs now',
  'blog.how-to-merge-pdf-files.cta.p': 'Open <tool_merge_pdf>Merge PDF</tool_merge_pdf>, or browse all of the <all_pdf>PDF tools</all_pdf>.',
  'blog.how-to-split-a-pdf.title': 'How to Split a PDF: Ranges, Single Pages and Chunks',
  'blog.how-to-split-a-pdf.description': 'Split a PDF by page ranges, into single pages or into equal parts, or extract just the pages you need, directly in your browser and without uploading the file.',
  'blog.how-to-split-a-pdf.excerpt': 'Break a large PDF into the parts you need, by range, page by page or in fixed-size chunks, and pick the right tool for each job.',
  'blog.how-to-split-a-pdf.imageAlt': 'One long PDF document being cut into separate smaller documents, shown on a teal background',
  'blog.how-to-split-a-pdf.intro.1': 'You have a 120-page scan and the person you are writing to needs pages 14 to 19. Or a report where every chapter must go to a different team. Or a bundle of invoices that arrived as one file and has to be filed one by one. Sending the whole document is slow, untidy and sometimes a privacy problem.',
  'blog.how-to-split-a-pdf.intro.2': 'Splitting solves all three. This guide explains the three ways to split a PDF, how to write page ranges that do what you mean, and when a different tool is a better fit.',
  'blog.how-to-split-a-pdf.sum.1': 'Split PDF can cut a file by custom ranges such as 1-3 and 4-6, into single pages, or into chunks of a fixed size.',
  'blog.how-to-split-a-pdf.sum.2': 'Download the parts one by one or all together as a ZIP.',
  'blog.how-to-split-a-pdf.sum.3': 'To keep only some pages as one new file, Extract PDF Pages is simpler; to delete pages, use Remove PDF Pages.',
  'blog.how-to-split-a-pdf.sum.4': 'Everything happens in your browser, so the document is never uploaded.',
  'blog.how-to-split-a-pdf.s1.h': 'Three ways to split a PDF',
  'blog.how-to-split-a-pdf.s1.p1': '<tool_split_pdf>Split PDF</tool_split_pdf> offers three modes, and picking the right one saves time.',
  'blog.how-to-split-a-pdf.s1.h1': 'Custom ranges',
  'blog.how-to-split-a-pdf.s1.p2': 'Use this when you know which pages go together. Type ranges separated by commas, for example 1-3, 4-6, 7-12. Each range becomes its own PDF. This is the mode for chapters, sections, and for pulling a single part out of a long document.',
  'blog.how-to-split-a-pdf.s1.h2': 'Every page',
  'blog.how-to-split-a-pdf.s1.p3': 'Use this when every page must be a separate file, such as invoices, tickets, payslips or certificates that were scanned in one run. You get one PDF per page.',
  'blog.how-to-split-a-pdf.s1.h3': 'Every N pages',
  'blog.how-to-split-a-pdf.s1.p4': 'Use this to cut a long file into equal pieces, for example every 10 pages. The last part contains whatever is left over, so a 25-page file split every 10 pages gives 10, 10 and 5.',
  'blog.how-to-split-a-pdf.s2.h': 'Step by step',
  'blog.how-to-split-a-pdf.s2.o1.1': 'Open the tool and add your PDF. It can be up to 100 MB.',
  'blog.how-to-split-a-pdf.s2.o1.2': 'Choose the mode: custom ranges, every page or every N pages.',
  'blog.how-to-split-a-pdf.s2.o1.3': 'For custom ranges, type the ranges. For the other modes, set the number if asked.',
  'blog.how-to-split-a-pdf.s2.o1.4': 'Press Split. The parts appear as a list.',
  'blog.how-to-split-a-pdf.s2.o1.5': 'Download each part, or take all of them together as a ZIP file.',
  'blog.how-to-split-a-pdf.s3.h': 'Writing page ranges that work',
  'blog.how-to-split-a-pdf.s3.p1': 'Ranges are written the way you would write them in a print dialog. A few examples show the pattern:',
  'blog.how-to-split-a-pdf.s3.l1.1': '1-3 means pages 1, 2 and 3 as one file.',
  'blog.how-to-split-a-pdf.s3.l1.2': '1-3, 4-6 means two files: one from pages 1 to 3 and one from pages 4 to 6.',
  'blog.how-to-split-a-pdf.s3.l1.3': '5 on its own means page 5 as a single-page file.',
  'blog.how-to-split-a-pdf.s3.p2': 'Page numbers are the position of the page in the file, counting from 1, not the number printed on the page. A document with a cover and a roman-numeral preface can have printed number 1 on its fifth page, and the tool counts the fifth page as 5. If a result looks off by a few pages, that is almost always the reason; open the PDF and check the position of the page in the viewer.',
  'blog.how-to-split-a-pdf.s3.n1': 'Tip: do a test with one short range first. Download it and check that it starts and ends on the pages you meant before you split the whole file.',
  'blog.how-to-split-a-pdf.s4.h': 'When Extract PDF Pages is the better tool',
  'blog.how-to-split-a-pdf.s4.p1': 'Split PDF makes several files. If you want one new file that contains a chosen set of pages, <tool_extract_pdf_pages>Extract PDF Pages</tool_extract_pdf_pages> is quicker. You click page thumbnails to select pages, or type a list such as 1-3, 8, and download one new PDF with exactly those pages in order. Use it for sending “just pages 4, 9 and 10” to someone.',
  'blog.how-to-split-a-pdf.s4.p2': 'If you only need to throw pages away, such as blank pages at the end of a scan, <tool_remove_pdf_pages>Remove PDF Pages</tool_remove_pdf_pages> deletes them and keeps everything else in one file.',
  'blog.how-to-split-a-pdf.s5.h': 'Splitting and merging go together',
  'blog.how-to-split-a-pdf.s5.p1': 'Two jobs come up again and again. The first is to take apart a pack, change one part and put it back together: split the file, edit or replace the part, then join the parts again with <tool_merge_pdf>Merge PDF</tool_merge_pdf>. Our guide to <post_how-to-merge-pdf-files>merging PDF files</post_how-to-merge-pdf-files> covers the order and limits.',
  'blog.how-to-split-a-pdf.s5.p2': 'The second is to rearrange a document. For a handful of pages, <tool_reorder_pdf_pages>Reorder PDF Pages</tool_reorder_pdf_pages> lets you drag thumbnails into a new order without splitting anything.',
  'blog.how-to-split-a-pdf.s6.h': 'Splitting to send a large PDF',
  'blog.how-to-split-a-pdf.s6.p1': 'Attachment limits are set by the receiving system. Many email services accept roughly 20 to 25 MB in total, and portals often allow far less. If a PDF is too large, splitting can help: send two files of half the size, or only the pages that matter. If the pages themselves are heavy, for example scans with photos, compressing is usually a better answer. Our guide to <post_compress-pdf-without-losing-quality>compressing a PDF without losing quality</post_compress-pdf-without-losing-quality> explains how to shrink a file while keeping text sharp.',
  'blog.how-to-split-a-pdf.s7.h': 'What to know before you split',
  'blog.how-to-split-a-pdf.s7.l1.1': 'Password-protected PDFs are not supported. If you know the password, remove it first with <tool_unlock_pdf>Unlock PDF</tool_unlock_pdf>.',
  'blog.how-to-split-a-pdf.s7.l1.2': 'Very large or complex files depend on your device memory. If a file will not process, split it in two stages, for example first by half, then each half by range.',
  'blog.how-to-split-a-pdf.s7.l1.3': 'The pages of each part keep their look, but a link that pointed to a page now in another part cannot work any more.',
  'blog.how-to-split-a-pdf.s7.l1.4': 'Bookmarks of the original file do not follow the parts, so rebuild them if you need them.',
  'blog.how-to-split-a-pdf.s8.h': 'Common situations',
  'blog.how-to-split-a-pdf.s8.l1.1': 'A scanned bundle of invoices: use Every page, then rename the files to match your filing system.',
  'blog.how-to-split-a-pdf.s8.l1.2': 'A long report for several readers: use custom ranges, one range per chapter.',
  'blog.how-to-split-a-pdf.s8.l1.3': 'A big file for an upload form with a page limit: use Every N pages, with N set to the form’s limit, and upload the parts one by one.',
  'blog.how-to-split-a-pdf.s8.l1.4': 'Only the signature page: use Extract PDF Pages and select that page.',
  'blog.how-to-split-a-pdf.faq.h': 'Frequently asked questions',
  'blog.how-to-split-a-pdf.faq.1.q': 'Does splitting a PDF reduce the quality?',
  'blog.how-to-split-a-pdf.faq.1.a': 'No. The pages are copied into the new files as they are, so text and images look the same as in the original.',
  'blog.how-to-split-a-pdf.faq.2.q': 'Can I split a PDF into single pages and get them all at once?',
  'blog.how-to-split-a-pdf.faq.2.a': 'Yes. Choose Every page and download the result as a ZIP file that contains one PDF per page.',
  'blog.how-to-split-a-pdf.faq.3.q': 'Is my PDF uploaded to a server when I split it?',
  'blog.how-to-split-a-pdf.faq.3.a': 'No. Split PDF works inside your browser tab, so the file stays on your device.',
  'blog.how-to-split-a-pdf.faq.4.q': 'What is the maximum file size?',
  'blog.how-to-split-a-pdf.faq.4.a': 'Up to 100 MB per PDF, although very large or complex files also depend on your device memory.',
  'blog.how-to-split-a-pdf.faq.5.q': 'How do I split a PDF that asks for a password?',
  'blog.how-to-split-a-pdf.faq.5.a': 'Remove the password first with Unlock PDF, which works when you know the password, then split the unlocked copy.',
  'blog.how-to-split-a-pdf.cta.h': 'Split your PDF now',
  'blog.how-to-split-a-pdf.cta.p': 'Open <tool_split_pdf>Split PDF</tool_split_pdf>, or browse all of the <all_pdf>PDF tools</all_pdf>.',
  'blog.jpg-vs-png-vs-webp.title': 'JPG vs PNG vs WebP: Which Image Format Should You Use?',
  'blog.jpg-vs-png-vs-webp.description': 'Compare JPG, PNG and WebP for photos, screenshots, logos and transparency. Learn when each is best and what is lost when you convert between them.',
  'blog.jpg-vs-png-vs-webp.excerpt': 'Pick the right image format for photos, screenshots and logos, and learn what converting between JPG, PNG and WebP really does.',
  'blog.jpg-vs-png-vs-webp.imageAlt': 'Three image tiles labelled JPG, PNG and WEBP side by side on a teal background',
  'blog.jpg-vs-png-vs-webp.intro.1': 'You save a screenshot and it is a PNG. Your phone saves photos as JPG, or sometimes as formats a website will not accept. A website asks for WebP. Every format has a reason to exist, and picking the wrong one means files that are bigger than needed, blurry text or a transparent logo with an ugly white box around it.',
  'blog.jpg-vs-png-vs-webp.intro.2': 'This guide compares the three formats you meet most often, in plain language, and shows how to convert between them without nasty surprises.',
  'blog.jpg-vs-png-vs-webp.sum.1': 'JPG is the universal format for photographs: small files, lossy, no transparency.',
  'blog.jpg-vs-png-vs-webp.sum.2': 'PNG is lossless and supports transparency: best for screenshots, logos and graphics, but large for photos.',
  'blog.jpg-vs-png-vs-webp.sum.3': 'WebP gives smaller files than JPG or PNG at similar quality and supports transparency, but needs a browser or service that accepts it.',
  'blog.jpg-vs-png-vs-webp.sum.4': 'Converting a JPG to PNG does not restore lost detail; it only changes the container.',
  'blog.jpg-vs-png-vs-webp.s1.h': 'JPG: the photo format',
  'blog.jpg-vs-png-vs-webp.s1.p1': 'JPG, also written JPEG, was designed for photographs. It stores an image by throwing away detail the eye is least likely to notice, which makes files small. The quality setting controls how much is thrown away.',
  'blog.jpg-vs-png-vs-webp.s1.p2': 'Strengths: small files for photos, supported everywhere, from phones to printers to every website and application. Weaknesses: no transparency, and repeated saving at lossy settings slowly degrades the picture. Sharp edges and text inside a JPG can show fuzzy halos at low quality.',
  'blog.jpg-vs-png-vs-webp.s2.h': 'PNG: the lossless format',
  'blog.jpg-vs-png-vs-webp.s2.p1': 'PNG keeps every pixel exactly as it is. Nothing is thrown away, so saving a PNG again and again causes no further loss. It also supports transparency, so a logo can sit on any background without a box around it.',
  'blog.jpg-vs-png-vs-webp.s2.p2': 'Strengths: perfect for screenshots, diagrams, logos, icons and anything with sharp edges or flat colours. Weaknesses: file sizes for photographs are much larger than JPG, because photos have little of the flat repetition PNG compresses well.',
  'blog.jpg-vs-png-vs-webp.s3.h': 'WebP: the modern all-rounder',
  'blog.jpg-vs-png-vs-webp.s3.p1': 'WebP was created for the web. It can compress like JPG (lossy) or like PNG (lossless), supports transparency and usually produces smaller files at similar visual quality.',
  'blog.jpg-vs-png-vs-webp.s3.p2': 'Strengths: smaller pages and faster loading, with transparency when you need it. Weaknesses: not every program, upload form or older device accepts it. If an application rejects your file, converting back to JPG or PNG is the fix. Browsers must also support WebP encoding for the tools to create it, and unsupported browsers show an error rather than a broken file.',
  'blog.jpg-vs-png-vs-webp.s4.h': 'A quick way to decide',
  'blog.jpg-vs-png-vs-webp.s4.l1.1': 'Photo to email, print or upload form: JPG.',
  'blog.jpg-vs-png-vs-webp.s4.l1.2': 'Screenshot or diagram with text: PNG.',
  'blog.jpg-vs-png-vs-webp.s4.l1.3': 'Logo or icon that must have a transparent background: PNG, or WebP if the destination supports it.',
  'blog.jpg-vs-png-vs-webp.s4.l1.4': 'Photo on your own website where speed matters: WebP, with JPG as the fallback if you need broad compatibility.',
  'blog.jpg-vs-png-vs-webp.s4.l1.5': 'Archive or editing copy where you want no loss: PNG.',
  'blog.jpg-vs-png-vs-webp.s5.h': 'Converting between formats in your browser',
  'blog.jpg-vs-png-vs-webp.s5.p1': 'Kitwell has a converter for each common pair. All of them work in your browser, so your pictures are not uploaded, and they accept up to 20 files of 25 MB each per batch:',
  'blog.jpg-vs-png-vs-webp.s5.l1.1': '<tool_jpg_to_png>JPG to PNG</tool_jpg_to_png>: when an application needs PNG, or you want to stop further quality loss from re-saving.',
  'blog.jpg-vs-png-vs-webp.s5.l1.2': '<tool_png_to_jpg>PNG to JPG</tool_png_to_jpg>: to make a photo or screenshot smaller, with adjustable quality.',
  'blog.jpg-vs-png-vs-webp.s5.l1.3': '<tool_jpg_to_webp>JPG to WebP</tool_jpg_to_webp> and <tool_png_to_webp>PNG to WebP</tool_png_to_webp>: for smaller web images.',
  'blog.jpg-vs-png-vs-webp.s5.l1.4': '<tool_webp_to_jpg>WebP to JPG</tool_webp_to_jpg> and <tool_webp_to_png>WebP to PNG</tool_webp_to_png>: when a site or program does not accept WebP.',
  'blog.jpg-vs-png-vs-webp.s6.h': 'What really changes when you convert',
  'blog.jpg-vs-png-vs-webp.s6.p1': 'Converting changes how the picture is stored, and each direction has a consequence:',
  'blog.jpg-vs-png-vs-webp.s6.l1.1': 'JPG to PNG: the file usually becomes larger, and the picture looks identical. It does not recover detail that the JPG compression already removed. PNG simply stops further loss.',
  'blog.jpg-vs-png-vs-webp.s6.l1.2': 'PNG to JPG: the file becomes smaller, but transparent areas must be filled with a solid colour, because JPG cannot store transparency. You choose that colour. Fine detail can soften slightly at lower quality.',
  'blog.jpg-vs-png-vs-webp.s6.l1.3': 'Anything to WebP: smaller file, same look at a sensible quality. Transparency is kept when converting from PNG.',
  'blog.jpg-vs-png-vs-webp.s6.l1.4': 'WebP to JPG or PNG: for compatibility. Going to JPG flattens transparency onto a colour; going to PNG keeps it.',
  'blog.jpg-vs-png-vs-webp.s6.n1': 'Tip: always convert from the best copy you have. A JPG made from another JPG, or from a screenshot of a JPG, is worse than one made from the original.',
  'blog.jpg-vs-png-vs-webp.s7.h': 'What is not preserved',
  'blog.jpg-vs-png-vs-webp.s7.p1': 'The converters read the pixels and write a new file. The camera information stored with a photo, such as EXIF data (date, location and camera model) and embedded colour profiles, is not carried over. That is good for privacy, but colours may look slightly different on some screens. Animated GIF or WebP files are converted using their first frame only.',
  'blog.jpg-vs-png-vs-webp.s8.h': 'Make files smaller after converting',
  'blog.jpg-vs-png-vs-webp.s8.p1': 'A new file in the right format can still be larger than you need. Run it through <tool_image_compressor>Image Compressor</tool_image_compressor> or lower the dimensions. Our guide to <post_reduce-image-size-in-kb>reducing image size in KB</post_reduce-image-size-in-kb> explains the order that gives the least visible damage. If the images are going into a document, <post_convert-images-to-pdf>turn them into a PDF</post_convert-images-to-pdf> afterwards.',
  'blog.jpg-vs-png-vs-webp.s9.h': 'Common mistakes',
  'blog.jpg-vs-png-vs-webp.s9.l1.1': 'Using PNG for photographs on a website, which makes pages slow for no visible gain.',
  'blog.jpg-vs-png-vs-webp.s9.l1.2': 'Saving a logo as JPG and getting a white box on a coloured background.',
  'blog.jpg-vs-png-vs-webp.s9.l1.3': 'Re-saving a JPG many times, which adds a little damage each time.',
  'blog.jpg-vs-png-vs-webp.s9.l1.4': 'Converting JPG to PNG to “improve quality”. It does not.',
  'blog.jpg-vs-png-vs-webp.s9.l1.5': 'Sending WebP to someone whose program cannot open it, without a JPG copy.',
  'blog.jpg-vs-png-vs-webp.faq.h': 'Frequently asked questions',
  'blog.jpg-vs-png-vs-webp.faq.1.q': 'Which is better, JPG or PNG?',
  'blog.jpg-vs-png-vs-webp.faq.1.a': 'Neither is better in general. JPG is better for photographs because the files are much smaller. PNG is better for screenshots, logos and anything with sharp edges or transparency.',
  'blog.jpg-vs-png-vs-webp.faq.2.q': 'Is WebP better than JPG?',
  'blog.jpg-vs-png-vs-webp.faq.2.a': 'WebP files are usually smaller at similar quality and WebP supports transparency. JPG is accepted by more programs and upload forms, so choose by where the image will be used.',
  'blog.jpg-vs-png-vs-webp.faq.3.q': 'Does converting JPG to PNG improve the quality?',
  'blog.jpg-vs-png-vs-webp.faq.3.a': 'No. The picture looks the same. PNG just prevents further loss when you save it again, and the file becomes larger.',
  'blog.jpg-vs-png-vs-webp.faq.4.q': 'Will my transparent PNG keep its transparency as a JPG?',
  'blog.jpg-vs-png-vs-webp.faq.4.a': 'No. JPG cannot store transparency, so transparent areas are filled with a solid background colour that you choose.',
  'blog.jpg-vs-png-vs-webp.faq.5.q': 'Are my pictures uploaded when I convert them?',
  'blog.jpg-vs-png-vs-webp.faq.5.a': 'No. The converters run in your browser, so the files stay on your device.',
  'blog.jpg-vs-png-vs-webp.cta.h': 'Convert an image now',
  'blog.jpg-vs-png-vs-webp.cta.p': 'Open <tool_png_to_jpg>PNG to JPG</tool_png_to_jpg>, or browse all of the <all_image>image tools</all_image>.',
  'blog.ocr-scanned-pdf-searchable.title': 'How to Make a Scanned PDF Searchable with OCR',
  'blog.ocr-scanned-pdf-searchable.description': 'Learn what OCR does, how to tell whether a PDF is a scan, and how to add a searchable text layer to scanned pages in your browser, with tips for better accuracy.',
  'blog.ocr-scanned-pdf-searchable.excerpt': 'A scanned PDF is a stack of pictures. See how OCR turns it into text you can search and copy, and how to get the best results.',
  'blog.ocr-scanned-pdf-searchable.imageAlt': 'A scanned page with a magnifying glass revealing selectable text lines, on a teal background',
  'blog.ocr-scanned-pdf-searchable.intro.1': 'You open a PDF, press Ctrl+F to look for a name, and nothing is found, even though you can see the name on the page. Or you try to copy a paragraph and the selection tool grabs the whole page as a picture. That PDF is a scan: every page is an image of text, not text itself.',
  'blog.ocr-scanned-pdf-searchable.intro.2': 'Optical character recognition, or OCR, reads the letters in those pictures and gives you real text back. This guide explains how it works, how to run it in your browser without uploading the document, and what to do when the results are not perfect.',
  'blog.ocr-scanned-pdf-searchable.sum.1': 'A scanned PDF is a stack of pictures; OCR reads the letters and adds a text layer you can search and copy.',
  'blog.ocr-scanned-pdf-searchable.sum.2': 'The recognition runs in your browser, so the scanned document is never uploaded.',
  'blog.ocr-scanned-pdf-searchable.sum.3': 'It reads English printed text; handwriting and other languages are unreliable.',
  'blog.ocr-scanned-pdf-searchable.sum.4': 'Scan quality matters more than any setting: 200 to 300 DPI, straight pages and good contrast.',
  'blog.ocr-scanned-pdf-searchable.s1.h': 'First, check whether your PDF is really a scan',
  'blog.ocr-scanned-pdf-searchable.s1.p1': 'Not every PDF needs OCR. A quick test: try to select a single word with the mouse, or search for a word you can see. If the word highlights, the PDF already contains text. If you can only drag a box over a whole region, or the search finds nothing, it is a scan.',
  'blog.ocr-scanned-pdf-searchable.s1.p2': '<tool_extract_pdf_text>Extract PDF Text</tool_extract_pdf_text> gives a clear answer as well. If a file has no selectable text, it says so and explains that reading it needs OCR.',
  'blog.ocr-scanned-pdf-searchable.s2.h': 'What OCR actually produces',
  'blog.ocr-scanned-pdf-searchable.s2.p1': 'The OCR tool recognises the text on each page and adds it as an invisible layer behind the picture. The pages look exactly as before, but you can now search them, select words and copy text. You can also download the recognised text as a plain text file.',
  'blog.ocr-scanned-pdf-searchable.s2.p2': 'Because the original page images are kept untouched, nothing about the look of your document changes. The text layer is only as good as the recognition, which is why checking the result matters.',
  'blog.ocr-scanned-pdf-searchable.s3.h': 'How to run OCR in your browser',
  'blog.ocr-scanned-pdf-searchable.s3.o1.1': 'Open <tool_ocr_pdf>OCR PDF</tool_ocr_pdf> and add your scanned PDF (up to 100 MB).',
  'blog.ocr-scanned-pdf-searchable.s3.o1.2': 'Choose the quality: Fast (150 DPI), Recommended (200 DPI), or Best for small print (300 DPI). Higher settings read smaller text but take longer.',
  'blog.ocr-scanned-pdf-searchable.s3.o1.3': 'Optionally limit the pages, for example 1-3, 5. Leave it empty to read every page. The option “Skip pages that already have selectable text” saves time on mixed documents.',
  'blog.ocr-scanned-pdf-searchable.s3.o1.4': 'Start recognition. Each page takes a few seconds, and you can cancel at any time.',
  'blog.ocr-scanned-pdf-searchable.s3.o1.5': 'Review the recognised text, then download the searchable PDF or the text file.',
  'blog.ocr-scanned-pdf-searchable.s4.h': 'What to know before you start',
  'blog.ocr-scanned-pdf-searchable.s4.l1.1': 'English only for now. Text in other languages is misread, and the tool says so up front rather than pretending otherwise.',
  'blog.ocr-scanned-pdf-searchable.s4.l1.2': 'The recognition engine (Tesseract, compiled to WebAssembly) and its English data are served from this website and run inside your browser. The first run loads about 3 MB, and your document is never uploaded.',
  'blog.ocr-scanned-pdf-searchable.s4.l1.3': 'Large documents are slow, because your own device does the work. For a long scan, process a page range at a time.',
  'blog.ocr-scanned-pdf-searchable.s5.h': 'Getting more accurate results',
  'blog.ocr-scanned-pdf-searchable.s5.p1': 'OCR quality depends far more on the scan than on the settings. These habits make the biggest difference:',
  'blog.ocr-scanned-pdf-searchable.s5.l1.1': 'Scan at 200 to 300 DPI. Lower resolutions blur small letters together; much higher ones only add file size and processing time.',
  'blog.ocr-scanned-pdf-searchable.s5.l1.2': 'Keep the page straight. A skewed page produces more errors, so re-scan if the text slopes noticeably.',
  'blog.ocr-scanned-pdf-searchable.s5.l1.3': 'Use good contrast. Dark text on a plain light background works best; shadows, folds and coloured backgrounds hurt.',
  'blog.ocr-scanned-pdf-searchable.s5.l1.4': 'Expect trouble with handwriting, very small print and decorative fonts. Recognition of these is unreliable.',
  'blog.ocr-scanned-pdf-searchable.s5.l1.5': 'Always check important numbers, such as amounts, dates and reference codes, against the page. A single misread digit can change the meaning.',
  'blog.ocr-scanned-pdf-searchable.s5.n1': 'Tip: if your scan came from photographs of pages, build it from straight, well-lit pictures with <tool_images_to_pdf>Images to PDF</tool_images_to_pdf> first. Our guide to <post_convert-images-to-pdf>converting images to PDF</post_convert-images-to-pdf> explains the options.',
  'blog.ocr-scanned-pdf-searchable.s6.h': 'Which quality setting should you choose?',
  'blog.ocr-scanned-pdf-searchable.s6.p1': 'The three settings trade speed against how small a letter the engine can still read. Fast (150 DPI) is fine for a quick look at a clean page of normal-sized text. Recommended (200 DPI) is the right starting point for most documents: letters, contracts, forms and book pages. Best for small print (300 DPI) is for fine print, footnotes, receipts and anything photographed from a distance, and it takes noticeably longer per page because there is more image to read.',
  'blog.ocr-scanned-pdf-searchable.s6.p2': 'If you are unsure, run Recommended on a page range of two or three pages first. Check those pages carefully, and only switch to Best if small characters are being misread. Re-running a whole long document at a higher setting is slow, so a short test saves time.',
  'blog.ocr-scanned-pdf-searchable.s7.h': 'How to check the result',
  'blog.ocr-scanned-pdf-searchable.s7.p1': 'OCR is never perfect, so build a short review into your routine instead of trusting the output blindly:',
  'blog.ocr-scanned-pdf-searchable.s7.o1.1': 'Search the finished PDF for a few words you can see on the page. If they are found, the text layer is aligned and working.',
  'blog.ocr-scanned-pdf-searchable.s7.o1.2': 'Copy a paragraph into a text editor and read it. Look for letters swapped with similar shapes, such as l, 1 and I, or 0 and O.',
  'blog.ocr-scanned-pdf-searchable.s7.o1.3': 'Check every number that matters: amounts, dates, account or reference codes, and phone numbers.',
  'blog.ocr-scanned-pdf-searchable.s7.o1.4': 'For contracts or legal documents, treat the text layer as a search aid and keep the original page images as the authoritative version.',
  'blog.ocr-scanned-pdf-searchable.s8.h': 'Scanned from a phone? Prepare the pages first',
  'blog.ocr-scanned-pdf-searchable.s8.p1': 'Photos of pages work, but they give weaker results than flat scans, because of perspective, shadows and uneven light. Straighten and crop each picture, then turn the set into a PDF with <tool_scan_to_pdf>Scan to PDF</tool_scan_to_pdf>. Its black and white document style evens out shadows and makes printed text darker, which gives the OCR engine cleaner letters to read. Run <tool_ocr_pdf>OCR PDF</tool_ocr_pdf> on the result.',
  'blog.ocr-scanned-pdf-searchable.s9.h': 'What to do next',
  'blog.ocr-scanned-pdf-searchable.s9.l1.1': 'Make the file smaller with <tool_compress_pdf>Compress PDF</tool_compress_pdf>. Scans are often large; see <post_compress-pdf-without-losing-quality>how to compress a PDF without losing quality</post_compress-pdf-without-losing-quality>.',
  'blog.ocr-scanned-pdf-searchable.s9.l1.2': 'Compare two versions of a document with <tool_compare_pdf>Compare PDF</tool_compare_pdf>. Comparing text works once both files have a text layer.',
  'blog.ocr-scanned-pdf-searchable.s9.l1.3': 'Hide private details before sharing with <tool_redact_pdf>Redact PDF</tool_redact_pdf>.',
  'blog.ocr-scanned-pdf-searchable.faq.h': 'Frequently asked questions',
  'blog.ocr-scanned-pdf-searchable.faq.1.q': 'Is my scanned document sent to an OCR service?',
  'blog.ocr-scanned-pdf-searchable.faq.1.a': 'No. The recognition engine and its data run inside your browser, so the document stays on your device.',
  'blog.ocr-scanned-pdf-searchable.faq.2.q': 'Does OCR change how my pages look?',
  'blog.ocr-scanned-pdf-searchable.faq.2.a': 'No. The original page images are kept as they are, and the recognised text is added as an invisible layer so that it can be searched and copied.',
  'blog.ocr-scanned-pdf-searchable.faq.3.q': 'How long does OCR take?',
  'blog.ocr-scanned-pdf-searchable.faq.3.a': 'A few seconds per page on a typical computer, longer at the highest quality setting and on large pages. Because your own device does the work, a slow phone or a very long scan will take more time. You can cancel at any time.',
  'blog.ocr-scanned-pdf-searchable.faq.4.q': 'Will the file get bigger after OCR?',
  'blog.ocr-scanned-pdf-searchable.faq.4.a': 'Slightly, because the text layer is added to the existing page images. If size matters, run Compress PDF afterwards.',
  'blog.ocr-scanned-pdf-searchable.faq.5.q': 'What if only some pages are scans?',
  'blog.ocr-scanned-pdf-searchable.faq.5.a': 'Use the option to skip pages that already have selectable text. Those pages are left untouched and only the scanned pages are processed.',
  'blog.ocr-scanned-pdf-searchable.faq.6.q': 'Can it read handwriting or languages other than English?',
  'blog.ocr-scanned-pdf-searchable.faq.6.a': 'Not reliably. The tool currently recognises English printed text. Handwriting and other languages produce many mistakes, so treat any result for them with caution.',
  'blog.ocr-scanned-pdf-searchable.cta.h': 'Try it yourself',
  'blog.ocr-scanned-pdf-searchable.cta.p': 'Open <tool_ocr_pdf>OCR PDF</tool_ocr_pdf>, or browse all of the <all_pdf>PDF tools</all_pdf>.',
  'blog.password-protect-and-unlock-a-pdf.title': 'How to Password-Protect and Unlock a PDF Safely',
  'blog.password-protect-and-unlock-a-pdf.description': 'Lock a PDF with AES-256 encryption, choose what readers may do, and unlock a file you own. Learn how passwords and permissions differ and what the limits are.',
  'blog.password-protect-and-unlock-a-pdf.excerpt': 'Learn how to protect a PDF with a strong password, how permissions differ from passwords, and how to unlock a file you have the password for.',
  'blog.password-protect-and-unlock-a-pdf.imageAlt': 'A PDF document with a padlock being closed, on a teal background',
  'blog.password-protect-and-unlock-a-pdf.intro.1': 'Payslips, medical letters, contracts, scans of identity documents: some PDFs should not be readable by whoever happens to find the attachment. A password is the simplest protection there is, and it travels with the file wherever it goes.',
  'blog.password-protect-and-unlock-a-pdf.intro.2': 'This guide explains how to protect a PDF with a password in your browser, how a password differs from permissions such as “no printing”, how to choose a password worth having, and how to remove protection from a file you own.',
  'blog.password-protect-and-unlock-a-pdf.sum.1': 'A document password stops anyone without it from opening the PDF; permissions only restrict actions such as printing or copying.',
  'blog.password-protect-and-unlock-a-pdf.sum.2': 'Protect PDF uses AES-256 encryption, and everything runs in your browser, so the file and the password are not uploaded.',
  'blog.password-protect-and-unlock-a-pdf.sum.3': 'Choose a long, unique password and share it through a different channel than the file.',
  'blog.password-protect-and-unlock-a-pdf.sum.4': 'Unlock PDF removes a password only when you provide the correct one; it never guesses passwords.',
  'blog.password-protect-and-unlock-a-pdf.s1.h': 'Passwords and permissions are different things',
  'blog.password-protect-and-unlock-a-pdf.s1.p1': 'A PDF can have two kinds of protection, and people often mix them up:',
  'blog.password-protect-and-unlock-a-pdf.s1.l1.1': 'A password to open. Without it the file cannot be read at all. This is real protection: the content is encrypted.',
  'blog.password-protect-and-unlock-a-pdf.s1.l1.2': 'Permissions. The file opens freely, but the reader program is asked not to allow printing, copying text or editing. These restrictions depend on the program obeying them, so treat them as a polite request, not as a lock.',
  'blog.password-protect-and-unlock-a-pdf.s1.p2': 'If the content must stay private, you need a password to open. Permissions are for convenience, for example to discourage casual copying of a document you are sharing widely.',
  'blog.password-protect-and-unlock-a-pdf.s2.h': 'How to protect a PDF in your browser',
  'blog.password-protect-and-unlock-a-pdf.s2.p1': '<tool_protect_pdf>Protect PDF</tool_protect_pdf> runs inside your browser tab. The document is read from your device, encrypted there and returned as a download.',
  'blog.password-protect-and-unlock-a-pdf.s2.o1.1': 'Open the tool and add your PDF (up to 100 MB). If it already has a password, unlock it first.',
  'blog.password-protect-and-unlock-a-pdf.s2.o1.2': 'Type the password twice to avoid typing mistakes.',
  'blog.password-protect-and-unlock-a-pdf.s2.o1.3': 'Choose what readers may do: print, copy or edit.',
  'blog.password-protect-and-unlock-a-pdf.s2.o1.4': 'Press Protect and download the encrypted copy.',
  'blog.password-protect-and-unlock-a-pdf.s2.o1.5': 'Open the new file and check that it asks for the password before you send it.',
  'blog.password-protect-and-unlock-a-pdf.s2.p2': 'Passwords can be up to 127 standard characters, made of letters, digits and symbols.',
  'blog.password-protect-and-unlock-a-pdf.s3.h': 'Choosing a password that is worth having',
  'blog.password-protect-and-unlock-a-pdf.s3.p1': 'Encryption is only as strong as the password. A short or guessable password can be tried automatically at enormous speed, however good the encryption.',
  'blog.password-protect-and-unlock-a-pdf.s3.l1.1': 'Length beats cleverness. A password of 14 or more characters is far harder to guess than a short one with symbols.',
  'blog.password-protect-and-unlock-a-pdf.s3.l1.2': 'Do not use names, birthdays, phone numbers or common words on their own.',
  'blog.password-protect-and-unlock-a-pdf.s3.l1.3': 'Never reuse a password you use elsewhere.',
  'blog.password-protect-and-unlock-a-pdf.s3.l1.4': 'Use a password manager to store it, instead of writing it in the email that carries the file.',
  'blog.password-protect-and-unlock-a-pdf.s3.p2': 'If you want a strong random password, <tool_password_generator>Password Generator</tool_password_generator> creates one in your browser using a cryptographic random source, and does not store or send it.',
  'blog.password-protect-and-unlock-a-pdf.s4.h': 'How to send a protected PDF safely',
  'blog.password-protect-and-unlock-a-pdf.s4.p1': 'The protection is only useful if the password does not travel next to the file. Send the PDF by email and the password by a different channel, such as a phone call or a messaging app. If the recipient needs it later, do not resend both together.',
  'blog.password-protect-and-unlock-a-pdf.s4.p2': 'Tell the recipient that they need a reader that supports modern encryption. AES-256 files open in current PDF programs and browsers, but very old readers, from before about 2008, may not open them.',
  'blog.password-protect-and-unlock-a-pdf.s5.h': 'How to unlock a PDF',
  'blog.password-protect-and-unlock-a-pdf.s5.p1': 'If you know the password and want a copy that opens without it, use <tool_unlock_pdf>Unlock PDF</tool_unlock_pdf>:',
  'blog.password-protect-and-unlock-a-pdf.s5.o1.1': 'Add the protected PDF.',
  'blog.password-protect-and-unlock-a-pdf.s5.o1.2': 'Enter its password if asked. A PDF that only restricts printing or copying needs no password to open.',
  'blog.password-protect-and-unlock-a-pdf.s5.o1.3': 'Download the unlocked copy.',
  'blog.password-protect-and-unlock-a-pdf.s5.p2': 'It supports standard PDF protection, including RC4 and AES encryption.',
  'blog.password-protect-and-unlock-a-pdf.s6.h': 'What Unlock PDF cannot do',
  'blog.password-protect-and-unlock-a-pdf.s6.p1': 'Be clear about the limits so you do not waste time:',
  'blog.password-protect-and-unlock-a-pdf.s6.l1.1': 'It does not crack or guess passwords. Without the correct password, a PDF that is encrypted for opening stays closed.',
  'blog.password-protect-and-unlock-a-pdf.s6.l1.2': 'It does not support certificate-based or rights-managed files.',
  'blog.password-protect-and-unlock-a-pdf.s6.l1.3': 'If a file carried a digital signature, re-saving it invalidates the signature, because the document has changed.',
  'blog.password-protect-and-unlock-a-pdf.s6.p2': 'Unlocking is meant for your own files, for example when you changed your mind about a password or must merge, edit or compress a protected PDF. Always respect the rights of whoever created the document.',
  'blog.password-protect-and-unlock-a-pdf.s7.h': 'When you need to unlock before another step',
  'blog.password-protect-and-unlock-a-pdf.s7.p1': 'Many tools cannot read an encrypted PDF. If you want to join protected files, remove the password first with Unlock PDF, then use <tool_merge_pdf>Merge PDF</tool_merge_pdf>; our guide to <post_how-to-merge-pdf-files>merging PDF files</post_how-to-merge-pdf-files> covers the rest. The same goes for compressing: unlock, compress, and protect again at the end. Our guide to <post_compress-pdf-without-losing-quality>compressing a PDF without losing quality</post_compress-pdf-without-losing-quality> explains the compression step.',
  'blog.password-protect-and-unlock-a-pdf.s7.p2': 'The best order for a document you send is: edit, merge or compress first, sign if needed, and protect last. If you need a signature on the document, see <post_sign-a-pdf-without-printing>how to sign a PDF without printing</post_sign-a-pdf-without-printing>, because Sign PDF cannot open a password-protected file.',
  'blog.password-protect-and-unlock-a-pdf.s8.h': 'Common mistakes',
  'blog.password-protect-and-unlock-a-pdf.s8.l1.1': 'Sending the password in the same email as the file.',
  'blog.password-protect-and-unlock-a-pdf.s8.l1.2': 'Using a short, guessable password such as a name plus a year.',
  'blog.password-protect-and-unlock-a-pdf.s8.l1.3': 'Forgetting the password. There is no recovery: keep it in a password manager.',
  'blog.password-protect-and-unlock-a-pdf.s8.l1.4': 'Protecting a file and then deleting the unprotected original without checking that the protected one opens.',
  'blog.password-protect-and-unlock-a-pdf.s8.l1.5': 'Assuming “no copying” permissions stop a determined person. Only a password to open protects the content.',
  'blog.password-protect-and-unlock-a-pdf.faq.h': 'Frequently asked questions',
  'blog.password-protect-and-unlock-a-pdf.faq.1.q': 'Is AES-256 encryption secure?',
  'blog.password-protect-and-unlock-a-pdf.faq.1.a': 'AES-256 is a strong, widely used standard. In practice, the password is the weak point, so the strength of your password decides how safe the file is.',
  'blog.password-protect-and-unlock-a-pdf.faq.2.q': 'Is my PDF or password uploaded when I protect it?',
  'blog.password-protect-and-unlock-a-pdf.faq.2.a': 'No. Protect PDF runs in your browser, so the file and the password stay on your device.',
  'blog.password-protect-and-unlock-a-pdf.faq.3.q': 'Can I remove a password from a PDF if I forgot it?',
  'blog.password-protect-and-unlock-a-pdf.faq.3.a': 'No. Unlock PDF needs the correct password and does not guess passwords. If you have lost it, the file cannot be opened by this tool.',
  'blog.password-protect-and-unlock-a-pdf.faq.4.q': 'Why will my protected PDF not open on an old device?',
  'blog.password-protect-and-unlock-a-pdf.faq.4.a': 'AES-256 requires a reasonably modern PDF reader. Very old programs, from before about 2008, may not support it. Use a current browser or reader.',
  'blog.password-protect-and-unlock-a-pdf.faq.5.q': 'What is the difference between protecting and signing a PDF?',
  'blog.password-protect-and-unlock-a-pdf.faq.5.a': 'Protecting controls who can open or use the file. Signing places a signature on it. They are separate steps, and signing is best done before you protect the file.',
  'blog.password-protect-and-unlock-a-pdf.cta.h': 'Protect your PDF now',
  'blog.password-protect-and-unlock-a-pdf.cta.p': 'Open <tool_protect_pdf>Protect PDF</tool_protect_pdf>, or browse all of the <all_pdf>PDF tools</all_pdf>.',
  'blog.reduce-image-size-in-kb.title': 'How to Reduce Image Size in KB Without Blurry Results',
  'blog.reduce-image-size-in-kb.description': 'Get a photo under an upload limit such as 200 KB or 1 MB. Learn how dimensions, format and quality work together, and how to check the result.',
  'blog.reduce-image-size-in-kb.excerpt': 'Shrink a photo to a target file size by combining the right format, quality and dimensions, without turning it into a blurry mess.',
  'blog.reduce-image-size-in-kb.imageAlt': 'A large photo shrinking into a small file size badge on a teal background',
  'blog.reduce-image-size-in-kb.intro.1': 'An application form that accepts photos “up to 200 KB”. A shop that rejects product images over 1 MB. A website that slows down because every picture is 4 MB. Phone cameras produce files far larger than most websites and forms want, and “make it smaller” is one of the most common image jobs there is.',
  'blog.reduce-image-size-in-kb.intro.2': 'The problem is doing it without wrecking the picture. This guide explains the three things that decide file size, in the order you should adjust them, so you reach your target with the least visible damage.',
  'blog.reduce-image-size-in-kb.sum.1': 'File size depends on three things: dimensions (pixels), format and quality. Change dimensions first, then quality.',
  'blog.reduce-image-size-in-kb.sum.2': 'JPG and WebP compress photos far better than PNG, which is lossless.',
  'blog.reduce-image-size-in-kb.sum.3': 'Most upload limits do not need a full-size photo: a width of 1,200 to 2,000 pixels is usually plenty on screen.',
  'blog.reduce-image-size-in-kb.sum.4': 'Check the result at the size it will be used, and keep your original.',
  'blog.reduce-image-size-in-kb.s1.h': 'What makes an image file large',
  'blog.reduce-image-size-in-kb.s1.p1': 'A photo is a grid of pixels, and each pixel needs data. A 12-megapixel phone photo has about 12 million pixels, so even compressed it often weighs 3 to 6 MB. Three things control the final size:',
  'blog.reduce-image-size-in-kb.s1.o1.1': 'Dimensions. Halving the width and height leaves a quarter of the pixels, which cuts the size by a lot. This is the most powerful setting and usually the least visible one, because screens rarely show a photo at full camera resolution.',
  'blog.reduce-image-size-in-kb.s1.o1.2': 'Format. JPG and WebP use lossy compression made for photographs. PNG is lossless and keeps every pixel exactly, which is ideal for logos and screenshots but gives large files for photos.',
  'blog.reduce-image-size-in-kb.s1.o1.3': 'Quality. For lossy formats, a quality setting trades detail for size. Lowering it removes fine detail, and below a certain point blocky artefacts and blur appear.',
  'blog.reduce-image-size-in-kb.s2.h': 'The order that works best',
  'blog.reduce-image-size-in-kb.s2.p1': 'Most people go straight to the quality slider and lower it until the file fits, which is why their pictures end up blurry. A better order is:',
  'blog.reduce-image-size-in-kb.s2.o1.1': 'Reduce the dimensions to the size you actually need.',
  'blog.reduce-image-size-in-kb.s2.o1.2': 'Switch to a better format for photos, such as JPG or WebP.',
  'blog.reduce-image-size-in-kb.s2.o1.3': 'Lower the quality in small steps, only as far as you need.',
  'blog.reduce-image-size-in-kb.s2.p2': 'Each step costs less quality than the next, so you only use the later ones if the earlier ones were not enough.',
  'blog.reduce-image-size-in-kb.s3.h': 'How to do it in your browser',
  'blog.reduce-image-size-in-kb.s3.p1': '<tool_image_compressor>Image Compressor</tool_image_compressor> works inside your browser, so your pictures are not uploaded. You can add up to 20 images at a time, each up to 25 MB.',
  'blog.reduce-image-size-in-kb.s3.o1.1': 'Add your images.',
  'blog.reduce-image-size-in-kb.s3.o1.2': 'Choose the output format and the quality. For photos, JPG or WebP at a medium-high quality is a good start.',
  'blog.reduce-image-size-in-kb.s3.o1.3': 'Optionally set a maximum width or height. This is the setting that does the heavy lifting.',
  'blog.reduce-image-size-in-kb.s3.o1.4': 'Press Compress. The tool shows the size before and after, so you can see the saving for every image.',
  'blog.reduce-image-size-in-kb.s3.o1.5': 'Download the results, and keep your original files unchanged.',
  'blog.reduce-image-size-in-kb.s3.p2': 'If the file is still too large, lower the maximum width or the quality a little and run it again from the original, not from the compressed copy.',
  'blog.reduce-image-size-in-kb.s4.h': 'Choosing dimensions',
  'blog.reduce-image-size-in-kb.s4.p1': 'Pick the size from where the image will be shown, not from what the camera produced:',
  'blog.reduce-image-size-in-kb.s4.l1.1': 'A picture inside a web page or blog post rarely needs to be wider than about 1,200 to 2,000 pixels.',
  'blog.reduce-image-size-in-kb.s4.l1.2': 'A profile picture or avatar often needs only a few hundred pixels on each side.',
  'blog.reduce-image-size-in-kb.s4.l1.3': 'An image that will be printed needs more pixels than one that will only be seen on a screen.',
  'blog.reduce-image-size-in-kb.s4.l1.4': 'Many forms and portals state exact pixel sizes next to the file size limit. Follow them.',
  'blog.reduce-image-size-in-kb.s4.p2': 'To set an exact width and height, or a percentage, use <tool_image_resizer>Image Resizer</tool_image_resizer>. Keep the aspect-ratio lock on so the picture is not stretched. Resizing and compressing together gives the best result for the least quality loss.',
  'blog.reduce-image-size-in-kb.s5.h': 'Choosing the format',
  'blog.reduce-image-size-in-kb.s5.l1.1': 'Photographs: JPG is the safe, universal choice. WebP gives smaller files at similar quality, but the receiving system must accept it.',
  'blog.reduce-image-size-in-kb.s5.l1.2': 'Screenshots, logos and graphics with sharp edges or flat colours: PNG keeps them crisp. If the file is too large, convert it to JPG or WebP, accepting some softness around edges.',
  'blog.reduce-image-size-in-kb.s5.l1.3': 'Images with a transparent background: PNG and WebP keep transparency. JPG cannot, so transparent areas are filled with a solid colour.',
  'blog.reduce-image-size-in-kb.s5.p1': 'If you need a specific format, <tool_png_to_jpg>PNG to JPG</tool_png_to_jpg> and <tool_jpg_to_webp>JPG to WebP</tool_jpg_to_webp> convert while letting you set the quality. Our guide to <post_jpg-vs-png-vs-webp>JPG, PNG and WebP</post_jpg-vs-png-vs-webp> explains when each is the right choice. If a site does not accept WebP, <tool_webp_to_jpg>WebP to JPG</tool_webp_to_jpg> converts it back.',
  'blog.reduce-image-size-in-kb.s6.h': 'Aiming for a specific size, such as 100 KB or 200 KB',
  'blog.reduce-image-size-in-kb.s6.p1': 'There is no way to say “make this exactly 200 KB” in one move, but a short routine gets you there:',
  'blog.reduce-image-size-in-kb.s6.o1.1': 'Set the maximum width to about 1,600 pixels and the format to JPG.',
  'blog.reduce-image-size-in-kb.s6.o1.2': 'Compress at a medium-high quality and read the new size.',
  'blog.reduce-image-size-in-kb.s6.o1.3': 'If it is still over, drop the width to 1,200 and compress again from the original.',
  'blog.reduce-image-size-in-kb.s6.o1.4': 'If it is far under the limit, raise the quality a little for a sharper picture.',
  'blog.reduce-image-size-in-kb.s6.o1.5': 'Stop as soon as the file fits. Anything smaller than necessary just costs quality.',
  'blog.reduce-image-size-in-kb.s7.h': 'How to judge the result',
  'blog.reduce-image-size-in-kb.s7.p1': 'Open the compressed image at the size it will actually be used. A picture that looks perfect when shrunk to a thumbnail can show blocky patches or smeared edges at full size. Look at fine detail: faces, text in the picture and areas of smooth gradient, such as a sky, which show compression first.',
  'blog.reduce-image-size-in-kb.s7.p2': 'If you see banding or blocks, raise the quality one step, or reduce the dimensions further instead of lowering the quality.',
  'blog.reduce-image-size-in-kb.s8.h': 'Things to keep in mind',
  'blog.reduce-image-size-in-kb.s8.l1.1': 'Compression removes the camera information stored in the file, such as the location and date, and colour profiles. This is useful for privacy, but it also means colours can shift slightly on some screens.',
  'blog.reduce-image-size-in-kb.s8.l1.2': 'Do not compress an image repeatedly. Every lossy round loses detail, so always start from the original.',
  'blog.reduce-image-size-in-kb.s8.l1.3': 'Animated GIF or WebP files are converted using their first frame only.',
  'blog.reduce-image-size-in-kb.s8.l1.4': 'Output from JPG or WebP shrinks best. PNG output is lossless and may not shrink at all.',
  'blog.reduce-image-size-in-kb.s9.h': 'Pictures that end up in a PDF',
  'blog.reduce-image-size-in-kb.s9.p1': 'If your images are going into a document, compress them before you build it, or compress the finished file. <tool_images_to_pdf>Images to PDF</tool_images_to_pdf> builds the PDF, and <tool_compress_pdf>Compress PDF</tool_compress_pdf> shrinks it afterwards. Our guide to <post_convert-images-to-pdf>converting images to PDF</post_convert-images-to-pdf> covers the page size and order.',
  'blog.reduce-image-size-in-kb.faq.h': 'Frequently asked questions',
  'blog.reduce-image-size-in-kb.faq.1.q': 'Does compressing an image reduce its quality?',
  'blog.reduce-image-size-in-kb.faq.1.a': 'With JPG and WebP, yes, a little: you trade fine detail for a smaller file. With a sensible quality setting and a sensible size, the difference is rarely visible at the size the picture is used.',
  'blog.reduce-image-size-in-kb.faq.2.q': 'What is the best format for a small file size?',
  'blog.reduce-image-size-in-kb.faq.2.a': 'For photos, WebP or JPG. PNG is lossless and usually the largest. Use PNG only when you need sharp edges or transparency.',
  'blog.reduce-image-size-in-kb.faq.3.q': 'Are my images uploaded when I compress them?',
  'blog.reduce-image-size-in-kb.faq.3.a': 'No. The tool works inside your browser, so the pictures stay on your device.',
  'blog.reduce-image-size-in-kb.faq.4.q': 'Why did my PNG not get smaller?',
  'blog.reduce-image-size-in-kb.faq.4.a': 'PNG is lossless, so compressing it with PNG output may save little or nothing. Choose JPG or WebP as the output, or reduce the dimensions.',
  'blog.reduce-image-size-in-kb.faq.5.q': 'How many images can I compress at once?',
  'blog.reduce-image-size-in-kb.faq.5.a': 'Up to 20 per batch, each up to 25 MB, to keep your browser responsive.',
  'blog.reduce-image-size-in-kb.cta.h': 'Compress an image now',
  'blog.reduce-image-size-in-kb.cta.p': 'Open <tool_image_compressor>Image Compressor</tool_image_compressor>, or browse all of the <all_image>image tools</all_image>.',
  'blog.repair-a-corrupted-pdf.title': 'How to Repair a Corrupted PDF That Will Not Open',
  'blog.repair-a-corrupted-pdf.description': 'Learn why PDFs get damaged, which problems a rebuild can fix and which it cannot, and how to repair a broken PDF in your browser without uploading the file.',
  'blog.repair-a-corrupted-pdf.excerpt': 'A PDF that will not open is not always lost. See what damage can be repaired, how to try it safely and what to do when it cannot be saved.',
  'blog.repair-a-corrupted-pdf.imageAlt': 'A cracked PDF document being mended with a wrench and a green check mark on a teal background',
  'blog.repair-a-corrupted-pdf.intro.1': 'You double-click a PDF and get “the file is damaged and could not be repaired”, a blank window, or a document that opens with half its pages missing. It might be an important report, a download that was interrupted, or an attachment that arrived broken. Before you ask for the file again, it is worth knowing that many of these cases can be repaired.',
  'blog.repair-a-corrupted-pdf.intro.2': 'This guide explains how a PDF is built, why it breaks, what a repair can and cannot recover, and how to try it safely.',
  'blog.repair-a-corrupted-pdf.sum.1': 'A PDF is a set of objects plus an index at the end; most “corrupted” files have a damaged or missing index, and the pages themselves are often intact.',
  'blog.repair-a-corrupted-pdf.sum.2': 'Repair PDF rebuilds the index and page structure in your browser and keeps the pages it can read.',
  'blog.repair-a-corrupted-pdf.sum.3': 'It cannot bring back content that is missing from the file, and damage inside compressed object streams cannot be rebuilt.',
  'blog.repair-a-corrupted-pdf.sum.4': 'If a file cannot be repaired, the tool says so and does not give you a download it did not create.',
  'blog.repair-a-corrupted-pdf.s1.h': 'Why a PDF stops opening',
  'blog.repair-a-corrupted-pdf.s1.p1': 'A PDF file is a collection of objects, such as pages, fonts and images, followed by a cross-reference table that lists where each object is, and a small trailer that points to the table. A viewer reads the trailer first, then uses the table to find everything else.',
  'blog.repair-a-corrupted-pdf.s1.p2': 'If the end of the file is damaged, the viewer cannot find the table, and it reports a corrupted file even when every page is still inside. The usual causes:',
  'blog.repair-a-corrupted-pdf.s1.l1.1': 'A download that stopped early, so the file is cut off and the end is missing.',
  'blog.repair-a-corrupted-pdf.s1.l1.2': 'An email gateway, a flaky USB drive or a cloud sync that wrote only part of the file.',
  'blog.repair-a-corrupted-pdf.s1.l1.3': 'A program that crashed while saving or exporting.',
  'blog.repair-a-corrupted-pdf.s1.l1.4': 'Extra data added before the PDF header, for example by a faulty export or transfer tool.',
  'blog.repair-a-corrupted-pdf.s1.l1.5': 'Real storage errors on a failing disk, which damage the content itself.',
  'blog.repair-a-corrupted-pdf.s2.h': 'First, quick checks',
  'blog.repair-a-corrupted-pdf.s2.p1': 'Before you try a repair, rule out the simple causes:',
  'blog.repair-a-corrupted-pdf.s2.o1.1': 'Open the file in a different program, such as your browser or another PDF reader. Some viewers are stricter than others.',
  'blog.repair-a-corrupted-pdf.s2.o1.2': 'Check the file size. A file that is only a few kilobytes, or far smaller than you expect, was probably cut off.',
  'blog.repair-a-corrupted-pdf.s2.o1.3': 'Download or copy it again from the source. A second transfer often fixes a damaged one.',
  'blog.repair-a-corrupted-pdf.s2.o1.4': 'If it is password-protected, make sure you are entering the password correctly. A protected file that fails to open is not necessarily corrupted. With the password, <tool_unlock_pdf>Unlock PDF</tool_unlock_pdf> removes the protection first.',
  'blog.repair-a-corrupted-pdf.s3.h': 'How to repair a PDF in your browser',
  'blog.repair-a-corrupted-pdf.s3.p1': '<tool_repair_pdf>Repair PDF</tool_repair_pdf> works inside your browser tab, so the damaged file is not uploaded anywhere.',
  'blog.repair-a-corrupted-pdf.s3.o1.1': 'Open the tool and choose the PDF (up to 100 MB). A password-protected file must be unlocked first.',
  'blog.repair-a-corrupted-pdf.s3.o1.2': 'Start the repair. The tool looks for the objects in the file, rebuilds the cross-reference table and trailer, and when needed gathers the pages it can read into a new page structure.',
  'blog.repair-a-corrupted-pdf.s3.o1.3': 'Read the report under the result. It lists the problems found, what was done and how many pages are in the repaired file.',
  'blog.repair-a-corrupted-pdf.s3.o1.4': 'If a file was produced, open it and check the pages before you rely on it, then download it.',
  'blog.repair-a-corrupted-pdf.s4.h': 'What a repair can fix',
  'blog.repair-a-corrupted-pdf.s4.p1': 'Repair works on the structure of the file:',
  'blog.repair-a-corrupted-pdf.s4.l1.1': 'A missing or wrong object list (the cross-reference table).',
  'blog.repair-a-corrupted-pdf.s4.l1.2': 'A missing trailer or end-of-file marker.',
  'blog.repair-a-corrupted-pdf.s4.l1.3': 'Junk data before the PDF header.',
  'blog.repair-a-corrupted-pdf.s4.l1.4': 'A broken page list.',
  'blog.repair-a-corrupted-pdf.s4.l1.5': 'A file that was cut off: the pages that were saved before the cut can often be recovered.',
  'blog.repair-a-corrupted-pdf.s4.p2': 'When the file opens fine but only had small structural problems, the tool says so and gives you a cleaned copy.',
  'blog.repair-a-corrupted-pdf.s5.h': 'What a repair cannot fix',
  'blog.repair-a-corrupted-pdf.s5.p1': 'Be realistic about the limits, because they are physical, not a matter of effort:',
  'blog.repair-a-corrupted-pdf.s5.l1.1': 'Content that is no longer in the file. If the end of a long document was never downloaded, those pages do not exist and cannot be reconstructed.',
  'blog.repair-a-corrupted-pdf.s5.l1.2': 'Damaged pages, images or fonts. A page whose data is broken cannot be brought back, so it may be left out of the repaired file.',
  'blog.repair-a-corrupted-pdf.s5.l1.3': 'Damage inside compressed object streams, which this tool cannot rebuild.',
  'blog.repair-a-corrupted-pdf.s5.l1.4': 'Some files are too damaged to save at all. In that case the tool tells you that nothing could be recovered; it never hands you a download that it did not create.',
  'blog.repair-a-corrupted-pdf.s5.p2': 'A repaired file may therefore have fewer pages than the original, and after a heavy repair the order of the pages can change. Always compare the page count and a few pages with what you expected.',
  'blog.repair-a-corrupted-pdf.s6.h': 'Checking a repaired file',
  'blog.repair-a-corrupted-pdf.s6.p1': 'A repaired PDF needs a quick inspection:',
  'blog.repair-a-corrupted-pdf.s6.o1.1': 'Open it and scroll through. Look for blank pages, garbled text and missing images.',
  'blog.repair-a-corrupted-pdf.s6.o1.2': 'Check the page count against what you expected.',
  'blog.repair-a-corrupted-pdf.s6.o1.3': 'Search for a word you know is inside. If the text is found, the text layer survived.',
  'blog.repair-a-corrupted-pdf.s6.o1.4': 'For important documents, ask the sender for a fresh copy as soon as possible, and treat the repaired file as a stop-gap.',
  'blog.repair-a-corrupted-pdf.s6.p2': 'If you only need the words from a document that opens badly, <tool_extract_pdf_text>Extract Text from PDF</tool_extract_pdf_text> can copy the selectable text out of a readable file, and <tool_pdf_to_jpg>PDF to JPG</tool_pdf_to_jpg> renders the pages as pictures.',
  'blog.repair-a-corrupted-pdf.s7.h': 'After the repair',
  'blog.repair-a-corrupted-pdf.s7.l1.1': 'A damaged file is often larger than it needs to be, so run <tool_compress_pdf>Compress PDF</tool_compress_pdf> on the repaired copy if size matters. Our guide to <post_compress-pdf-without-losing-quality>compressing a PDF without losing quality</post_compress-pdf-without-losing-quality> covers the options.',
  'blog.repair-a-corrupted-pdf.s7.l1.2': 'If you were about to combine files, repair the broken one first and then use <tool_merge_pdf>Merge PDF</tool_merge_pdf>; <post_how-to-merge-pdf-files>how to merge PDF files</post_how-to-merge-pdf-files> explains the order and limits.',
  'blog.repair-a-corrupted-pdf.s8.h': 'How to avoid damaged PDFs',
  'blog.repair-a-corrupted-pdf.s8.l1.1': 'Let downloads finish and compare the file size with what the source states.',
  'blog.repair-a-corrupted-pdf.s8.l1.2': 'Do not unplug a drive while a file is being saved or copied.',
  'blog.repair-a-corrupted-pdf.s8.l1.3': 'Keep a second copy of important documents in another place.',
  'blog.repair-a-corrupted-pdf.s8.l1.4': 'Avoid renaming a file’s extension to change its type; a file with the wrong extension is a common cause of “cannot open”.',
  'blog.repair-a-corrupted-pdf.s8.l1.5': 'Export from the program again if you can. A fresh export is better than any repair.',
  'blog.repair-a-corrupted-pdf.faq.h': 'Frequently asked questions',
  'blog.repair-a-corrupted-pdf.faq.1.q': 'Can every corrupted PDF be repaired?',
  'blog.repair-a-corrupted-pdf.faq.1.a': 'No. Structural damage, such as a missing index or a cut-off end, can often be repaired. Missing or broken content cannot be recreated, and some files are too damaged to save. The tool tells you when it cannot produce a usable file.',
  'blog.repair-a-corrupted-pdf.faq.2.q': 'Is my PDF uploaded when I repair it?',
  'blog.repair-a-corrupted-pdf.faq.2.a': 'No. Repair PDF works inside your browser, so the file stays on your device.',
  'blog.repair-a-corrupted-pdf.faq.3.q': 'Why does the repaired PDF have fewer pages?',
  'blog.repair-a-corrupted-pdf.faq.3.a': 'Pages whose data was missing or damaged cannot be recovered, so they are left out. The report under the result states how many pages were kept.',
  'blog.repair-a-corrupted-pdf.faq.4.q': 'What if my PDF opens but looks wrong?',
  'blog.repair-a-corrupted-pdf.faq.4.a': 'Then it may not be corrupted at all. The tool will report that no repair was needed and give you a cleaned copy. Wrong-looking text or missing fonts usually come from the program that created the file.',
  'blog.repair-a-corrupted-pdf.faq.5.q': 'Can it repair a password-protected PDF?',
  'blog.repair-a-corrupted-pdf.faq.5.a': 'Not directly. Unlock the file first with the password, then repair the unlocked copy.',
  'blog.repair-a-corrupted-pdf.cta.h': 'Try to repair your PDF',
  'blog.repair-a-corrupted-pdf.cta.p': 'Open <tool_repair_pdf>Repair PDF</tool_repair_pdf>, or browse all of the <all_pdf>PDF tools</all_pdf>.',
  'blog.sign-a-pdf-without-printing.title': 'How to Sign a PDF Without Printing (and What It Means)',
  'blog.sign-a-pdf-without-printing.description': 'Draw, type or upload a signature and place it on a PDF in your browser. Learn how a visual signature differs from a digital signature.',
  'blog.sign-a-pdf-without-printing.excerpt': 'Sign a PDF on your computer or phone without printing or scanning, and understand what a visual signature does and does not prove.',
  'blog.sign-a-pdf-without-printing.imageAlt': 'A pen drawing a signature line onto a PDF page on a teal background',
  'blog.sign-a-pdf-without-printing.intro.1': 'The classic routine is silly: print the form, sign it with a pen, scan it again, and email the scan. It wastes paper and time, and the scan often comes out crooked and grey. Placing your signature on the PDF directly is faster and looks cleaner.',
  'blog.sign-a-pdf-without-printing.intro.2': 'But there is something to know before you do it. “Signing a PDF” can mean two different things, and which one you need depends on who asked for the signature. This guide shows how to add a signature in your browser, and explains the difference so you do not send the wrong kind.',
  'blog.sign-a-pdf-without-printing.sum.1': 'Sign PDF places a picture of your signature on the pages you choose; you can draw it, type your name or upload an image.',
  'blog.sign-a-pdf-without-printing.sum.2': 'It is a visual signature: no certificate, no timestamp and no tamper detection.',
  'blog.sign-a-pdf-without-printing.sum.3': 'Many everyday forms accept it; contracts that require a digital or qualified signature do not.',
  'blog.sign-a-pdf-without-printing.sum.4': 'The file is processed in your browser and not uploaded; password-protected PDFs must be unlocked first.',
  'blog.sign-a-pdf-without-printing.s1.h': 'Two kinds of PDF signature',
  'blog.sign-a-pdf-without-printing.s1.p1': 'A visual signature is an image of your handwritten signature, or of your typed name, placed on the page. It looks like a signature and is accepted wherever a scanned, hand-signed copy is accepted: many internal forms, school and club documents, delivery receipts, consent slips and simple agreements.',
  'blog.sign-a-pdf-without-printing.s1.p2': 'A digital signature is a different technology. It is created with a certificate that identifies you, it records the time, and it makes the document show a warning if anyone changes it afterwards. It is used where the law or a contract requires proof of who signed and that the document did not change.',
  'blog.sign-a-pdf-without-printing.s1.p3': 'Sign PDF creates the first kind. It does not create certificates, timestamps or tamper-evident signatures, and it will not fill a signature form field. If the person asking for your signature needs a digital or qualified signature, ask which service or format they accept before you sign.',
  'blog.sign-a-pdf-without-printing.s2.h': 'How to sign a PDF in your browser',
  'blog.sign-a-pdf-without-printing.s2.p1': '<tool_sign_pdf>Sign PDF</tool_sign_pdf> runs on your own device. The document and your signature never leave your browser.',
  'blog.sign-a-pdf-without-printing.s2.o1.1': 'Add the PDF you need to sign (up to 100 MB). If it is password-protected, unlock it first.',
  'blog.sign-a-pdf-without-printing.s2.o1.2': 'Create your signature. Draw it with the mouse, a trackpad or your finger, type your name, or upload a picture of a signature.',
  'blog.sign-a-pdf-without-printing.s2.o1.3': 'Drag the signature to the right place on the page. Resize it so it fits the signature line.',
  'blog.sign-a-pdf-without-printing.s2.o1.4': 'Choose which pages get the signature. Many documents need it on one page; some need initials on every page.',
  'blog.sign-a-pdf-without-printing.s2.o1.5': 'Download the signed PDF and open it to check the position.',
  'blog.sign-a-pdf-without-printing.s3.h': 'Making a signature that looks good',
  'blog.sign-a-pdf-without-printing.s3.l1.1': 'Draw on a touch screen if you can. A finger or stylus gives a more natural line than a mouse.',
  'blog.sign-a-pdf-without-printing.s3.l1.2': 'If you upload a picture, sign with a dark pen on plain white paper, take a straight, well-lit photo and crop it tightly. A messy photo leaves grey edges around the signature.',
  'blog.sign-a-pdf-without-printing.s3.l1.3': 'Keep it a sensible size. A signature that overlaps the printed line or other text looks careless.',
  'blog.sign-a-pdf-without-printing.s3.l1.4': 'Use the same style each time, so your signature stays recognisable.',
  'blog.sign-a-pdf-without-printing.s4.h': 'What the signature is, technically',
  'blog.sign-a-pdf-without-printing.s4.p1': 'The signature is placed as a picture on top of the page. That has two practical consequences. It does not become part of a signature field in the document, and anyone with the right tools could remove or move it, because nothing protects it. The tool is honest about this limit so that you can choose the right method for important documents.',
  'blog.sign-a-pdf-without-printing.s4.n1': 'Tip: for anything that matters, keep the unsigned original and the signed copy together, and note the date you signed.',
  'blog.sign-a-pdf-without-printing.s5.h': 'When a visual signature is enough, and when it is not',
  'blog.sign-a-pdf-without-printing.s5.p1': 'Usually enough: forms inside a company or school, rental or club applications where a scanned signature is accepted, documents the recipient will print anyway, and receipts or acknowledgements with no legal weight.',
  'blog.sign-a-pdf-without-printing.s5.p2': 'Ask first: loans, property documents, contracts of employment, tax or government filings. Some require an electronic signature service or a certificate. Others say explicitly that a scan of a hand-signed page is fine. The sender knows, so ask before you sign.',
  'blog.sign-a-pdf-without-printing.s6.h': 'Before and after signing',
  'blog.sign-a-pdf-without-printing.s6.p1': 'Prepare the file first. If the document is a Word file, convert it to PDF before signing; our guide to <post_word-to-pdf-without-losing-formatting>converting Word to PDF</post_word-to-pdf-without-losing-formatting> explains what to expect. If it is a bundle, join the pieces with <tool_merge_pdf>Merge PDF</tool_merge_pdf>; our guide to <post_how-to-merge-pdf-files>merging PDF files</post_how-to-merge-pdf-files> explains the order. If only one page needs a signature, <tool_extract_pdf_pages>Extract PDF Pages</tool_extract_pdf_pages> can pull that page out as its own file.',
  'blog.sign-a-pdf-without-printing.s6.p2': 'After signing, check the file size, since a document with scans can be large. <tool_compress_pdf>Compress PDF</tool_compress_pdf> makes it smaller; our guide to <post_compress-pdf-without-losing-quality>compressing a PDF without losing quality</post_compress-pdf-without-losing-quality> explains the options.',
  'blog.sign-a-pdf-without-printing.s6.p3': 'If the signed document should only be read by one person, add a password last with <tool_protect_pdf>Protect PDF</tool_protect_pdf>. Our guide to <post_password-protect-and-unlock-a-pdf>protecting and unlocking a PDF</post_password-protect-and-unlock-a-pdf> explains why the order matters: sign first, protect last. If the file already has a password, remove it with <tool_unlock_pdf>Unlock PDF</tool_unlock_pdf> before signing.',
  'blog.sign-a-pdf-without-printing.s7.h': 'Keeping your signature safe',
  'blog.sign-a-pdf-without-printing.s7.p1': 'Your signature image is a piece of personal information. Do not leave copies on shared computers, and do not paste it into documents you do not control. This tool does not store your signature, because it never leaves your browser; close the tab and it is gone.',
  'blog.sign-a-pdf-without-printing.faq.h': 'Frequently asked questions',
  'blog.sign-a-pdf-without-printing.faq.1.q': 'Is a signature added with Sign PDF legally valid?',
  'blog.sign-a-pdf-without-printing.faq.1.a': 'It depends on the document and the country. It is a visual signature, comparable to a scanned hand-signed copy. It has no certificate or timestamp. For contracts that need a digital or qualified signature, ask the other party what they accept.',
  'blog.sign-a-pdf-without-printing.faq.2.q': 'Can I sign on my phone?',
  'blog.sign-a-pdf-without-printing.faq.2.a': 'Yes. The tool works in a mobile browser, and drawing with a finger works well. Large documents are slower on phones because your device does the work.',
  'blog.sign-a-pdf-without-printing.faq.3.q': 'Is my signature or document uploaded anywhere?',
  'blog.sign-a-pdf-without-printing.faq.3.a': 'No. Everything happens in your browser, and nothing is sent to a server.',
  'blog.sign-a-pdf-without-printing.faq.4.q': 'Can I put the signature on every page?',
  'blog.sign-a-pdf-without-printing.faq.4.a': 'Yes. You choose which pages receive it, which is useful for initials on every page.',
  'blog.sign-a-pdf-without-printing.faq.5.q': 'Why can I not open my PDF in the tool?',
  'blog.sign-a-pdf-without-printing.faq.5.a': 'It may be password-protected. Remove the password with Unlock PDF, sign the unlocked copy and protect it again afterwards if needed.',
  'blog.sign-a-pdf-without-printing.cta.h': 'Sign your PDF now',
  'blog.sign-a-pdf-without-printing.cta.p': 'Open <tool_sign_pdf>Sign PDF</tool_sign_pdf>, or browse all of the <all_pdf>PDF tools</all_pdf>.',
  'blog.what-is-base64-encoding.title': 'What Is Base64 Encoding? Uses, Limits and Examples',
  'blog.what-is-base64-encoding.description': 'Learn what Base64 is, why it makes data a third larger, where it is used and why it is not encryption, and how to encode and decode in your browser.',
  'blog.what-is-base64-encoding.excerpt': 'Base64 turns any data into plain text characters. Learn where it is used, what it costs and what it is not: a way to keep secrets.',
  'blog.what-is-base64-encoding.imageAlt': 'Binary ones and zeros turning into a string of letters and digits on a teal background',
  'blog.what-is-base64-encoding.intro.1': 'You open an email source, an API response or a CSS file and meet a long run of letters and digits ending in one or two equals signs. That is probably Base64. It shows up in web pages, tokens, configuration files and email attachments, usually without anyone explaining what it is.',
  'blog.what-is-base64-encoding.intro.2': 'This guide explains Base64 in plain language: what problem it solves, how it works, what it costs, and the most important thing to remember about it, which is that it is encoding, not encryption.',
  'blog.what-is-base64-encoding.sum.1': 'Base64 represents any data using only 64 safe text characters, so it can travel through systems built for text.',
  'blog.what-is-base64-encoding.sum.2': 'The encoded text is about 33% larger than the original data.',
  'blog.what-is-base64-encoding.sum.3': 'It is not encryption: anyone can decode it, so never use it to hide a secret.',
  'blog.what-is-base64-encoding.sum.4': 'Text, and images through the dedicated tools, can be encoded and decoded in your browser without uploading anything.',
  'blog.what-is-base64-encoding.s1.h': 'The problem Base64 solves',
  'blog.what-is-base64-encoding.s1.p1': 'Many systems were designed to carry text, not raw bytes. Email, parts of URLs, JSON and HTML can break, or alter data, when they meet arbitrary binary values such as an image or a file. Control characters get stripped, line breaks get changed, and bytes that are not valid text get mangled.',
  'blog.what-is-base64-encoding.s1.p2': 'Base64 avoids the problem by translating any sequence of bytes into a limited alphabet of 64 characters that every text system handles safely: the capital letters, the lowercase letters, the digits, plus and slash. The result is plain text that can be copied, pasted, stored in JSON or placed in an email without damage, and later turned back into the exact original bytes.',
  'blog.what-is-base64-encoding.s2.h': 'How it works, in short',
  'blog.what-is-base64-encoding.s2.p1': 'Base64 takes the data three bytes at a time. Three bytes are 24 bits, which it splits into four groups of 6 bits. Each 6-bit group is a number from 0 to 63, and each number is mapped to one character of the alphabet. Three bytes in, four characters out.',
  'blog.what-is-base64-encoding.s2.p2': 'When the data does not divide evenly by three, the end is padded with one or two equals signs. That is why many Base64 strings finish with = or ==. A variant called URL-safe Base64 swaps plus and slash for minus and underscore, so the text can sit inside a web address, and often leaves out the padding.',
  'blog.what-is-base64-encoding.s3.h': 'Why the result is bigger',
  'blog.what-is-base64-encoding.s3.p1': 'Four characters for every three bytes means the output is about one third larger than the input, plus a little for padding and any line breaks. A 300 KB image becomes roughly 400 KB of text. This is the price of using only safe characters, and it is the main reason not to Base64-encode large files when you can avoid it.',
  'blog.what-is-base64-encoding.s4.h': 'Where you meet Base64',
  'blog.what-is-base64-encoding.s4.l1.1': 'Images and fonts embedded directly in HTML or CSS as data URIs, which start with data: followed by a type and base64.',
  'blog.what-is-base64-encoding.s4.l1.2': 'Email attachments, which are encoded so they can travel inside text messages.',
  'blog.what-is-base64-encoding.s4.l1.3': 'Web tokens such as JWTs, whose parts use the URL-safe variant.',
  'blog.what-is-base64-encoding.s4.l1.4': 'HTTP basic authentication headers, where the username and password are encoded, not protected.',
  'blog.what-is-base64-encoding.s4.l1.5': 'Binary values stored inside JSON or XML, which cannot hold raw bytes.',
  'blog.what-is-base64-encoding.s4.l1.6': 'Certificates and keys in text formats.',
  'blog.what-is-base64-encoding.s5.h': 'Base64 is not encryption',
  'blog.what-is-base64-encoding.s5.p1': 'This point causes real security mistakes. Base64 is a public, reversible way of writing data. Anyone can decode it in a second, with no key or password. Encoding a password or a token in Base64 hides nothing.',
  'blog.what-is-base64-encoding.s5.p2': 'If something must stay secret, it needs real encryption, or better, it should never be put in the page, URL or message at all. If you see Base64 in a header or a configuration file, assume that whoever can read the file can read the value.',
  'blog.what-is-base64-encoding.s6.h': 'How to encode and decode text in your browser',
  'blog.what-is-base64-encoding.s6.p1': '<tool_base64_encoder_decoder>Base64 Encoder / Decoder</tool_base64_encoder_decoder> works entirely in your browser, so what you paste is not sent to a server. It handles the full range of text, including accented letters, scripts such as Arabic, Chinese or Cyrillic, and emoji, because it encodes text as UTF-8 first.',
  'blog.what-is-base64-encoding.s6.o1.1': 'Choose Encode or Decode.',
  'blog.what-is-base64-encoding.s6.o1.2': 'Paste your text.',
  'blog.what-is-base64-encoding.s6.o1.3': 'Copy the result.',
  'blog.what-is-base64-encoding.s6.p2': 'If decoding fails, the input is not valid Base64. Common causes are stray spaces or line breaks, a missing character, or text that is actually URL-safe Base64 using minus and underscore. Remove surrounding whitespace and check the ending first.',
  'blog.what-is-base64-encoding.s7.h': 'Images and Base64',
  'blog.what-is-base64-encoding.s7.p1': 'An image can be turned into a Base64 string and back. <tool_image_to_base64>Image to Base64</tool_image_to_base64> produces the text you can place in HTML or CSS, and <tool_base64_to_image>Base64 to Image</tool_base64_to_image> turns such a string back into a picture you can save. This is handy for tiny icons you want to embed to save a request. For anything larger than a few kilobytes, a normal image file is better: it loads separately, can be cached by the browser and does not add a third to its size inside your page. If the picture is too heavy to embed, shrink it first; our guide to <post_reduce-image-size-in-kb>reducing image size in KB</post_reduce-image-size-in-kb> shows how.',
  'blog.what-is-base64-encoding.s8.h': 'Base64, URL encoding and JSON',
  'blog.what-is-base64-encoding.s8.p1': 'These three are often confused, but they solve different problems:',
  'blog.what-is-base64-encoding.s8.l1.1': 'Base64 turns arbitrary bytes into safe text.',
  'blog.what-is-base64-encoding.s8.l1.2': 'URL encoding, also called percent-encoding, makes text safe to place inside a web address, replacing unsafe characters with a percent sign and two digits. <tool_url_encoder_decoder>URL Encoder / Decoder</tool_url_encoder_decoder> does it.',
  'blog.what-is-base64-encoding.s8.l1.3': 'JSON is a structure for data. A JSON string can hold a Base64 value, and our guide to <post_how-to-format-and-validate-json>formatting and validating JSON</post_how-to-format-and-validate-json> shows how to keep it valid.',
  'blog.what-is-base64-encoding.s8.p2': 'Text that contains HTML special characters is a fourth case, handled by <tool_html_encoder_decoder>HTML Encoder / Decoder</tool_html_encoder_decoder>.',
  'blog.what-is-base64-encoding.s9.h': 'Common mistakes',
  'blog.what-is-base64-encoding.s9.l1.1': 'Treating Base64 as a way to keep a password or token private.',
  'blog.what-is-base64-encoding.s9.l1.2': 'Embedding large images as Base64 in a page, which bloats it and cannot be cached separately.',
  'blog.what-is-base64-encoding.s9.l1.3': 'Forgetting that the data grows by about a third when you store or send it.',
  'blog.what-is-base64-encoding.s9.l1.4': 'Copying a string with a line break or space in the middle, which makes decoding fail.',
  'blog.what-is-base64-encoding.s9.l1.5': 'Mixing the standard and URL-safe alphabets and then wondering why a decoder rejects the text.',
  'blog.what-is-base64-encoding.faq.h': 'Frequently asked questions',
  'blog.what-is-base64-encoding.faq.1.q': 'Is Base64 a form of encryption?',
  'blog.what-is-base64-encoding.faq.1.a': 'No. It is an encoding that anyone can reverse without a key. Never use it to protect a secret.',
  'blog.what-is-base64-encoding.faq.2.q': 'Why does Base64 make data bigger?',
  'blog.what-is-base64-encoding.faq.2.a': 'It uses four text characters for every three bytes of data, so the output is about 33% larger than the input.',
  'blog.what-is-base64-encoding.faq.3.q': 'What do the equals signs at the end mean?',
  'blog.what-is-base64-encoding.faq.3.a': 'They are padding. They fill the last group when the data length is not a multiple of three bytes, so you will see one or two of them at the end of many strings.',
  'blog.what-is-base64-encoding.faq.4.q': 'Can Base64 handle non-English text and emoji?',
  'blog.what-is-base64-encoding.faq.4.a': 'Yes. The text is converted to UTF-8 bytes before it is encoded, so any language and emoji can be encoded and decoded correctly.',
  'blog.what-is-base64-encoding.faq.5.q': 'Is my text uploaded when I use the tool?',
  'blog.what-is-base64-encoding.faq.5.a': 'No. The encoding and decoding happen in your browser and nothing is sent to a server.',
  'blog.what-is-base64-encoding.cta.h': 'Encode or decode now',
  'blog.what-is-base64-encoding.cta.p': 'Open <tool_base64_encoder_decoder>Base64 Encoder / Decoder</tool_base64_encoder_decoder>, or browse all of the <all_developer>developer tools</all_developer>.',
  'blog.word-to-pdf-without-losing-formatting.title': 'Word to PDF Without Losing Formatting: What to Expect',
  'blog.word-to-pdf-without-losing-formatting.description': 'Convert a DOCX file to PDF in your browser. See what is kept, what is approximated, and how to prepare your document so the PDF comes out clean.',
  'blog.word-to-pdf-without-losing-formatting.excerpt': 'An honest look at converting Word documents to PDF in the browser: what carries over, what changes and how to prepare the file.',
  'blog.word-to-pdf-without-losing-formatting.imageAlt': 'A Word document page transforming into a PDF page with a red PDF label on a teal background',
  'blog.word-to-pdf-without-losing-formatting.intro.1': 'A PDF looks the same on every device, which is why people ask for one when you send a CV, a contract, an assignment or an invoice. A Word file can look different on another computer, with different fonts and shifted page breaks. Converting to PDF fixes the look in place.',
  'blog.word-to-pdf-without-losing-formatting.intro.2': 'The catch is that no converter reproduces a Word document exactly unless it is Word itself. This guide explains what a browser-based conversion keeps, what it only approximates, and how to prepare your document so that the PDF comes out as close as possible to what you expect.',
  'blog.word-to-pdf-without-losing-formatting.sum.1': 'Word to PDF converts DOCX files; old .doc files and password-protected documents are not supported.',
  'blog.word-to-pdf-without-losing-formatting.sum.2': 'Text formatting, headings, lists, tables, links and JPEG and PNG pictures are kept.',
  'blog.word-to-pdf-without-losing-formatting.sum.3': 'Headers, footers, footnotes, text boxes, equations, charts and shapes are not reproduced, and fonts are replaced by Noto Sans.',
  'blog.word-to-pdf-without-losing-formatting.sum.4': 'The tool lists what it could not convert, so check the result before you send it.',
  'blog.word-to-pdf-without-losing-formatting.s1.h': 'If you have Word, use its own export first',
  'blog.word-to-pdf-without-losing-formatting.s1.p1': 'If Microsoft Word or a compatible office program is installed on your computer, its built-in Save as PDF (or Export) gives the most faithful result, because the same program that laid out the document writes the PDF. Nothing else can do better.',
  'blog.word-to-pdf-without-losing-formatting.s1.p2': 'A browser tool is for the other situations: you are on a computer or phone without Word, you only have the file, you do not want to install anything, or you need a quick conversion of a simple document. In those cases <tool_word_to_pdf>Word to PDF</tool_word_to_pdf> does the job, as long as you know its limits.',
  'blog.word-to-pdf-without-losing-formatting.s2.h': 'How to convert a Word file to PDF',
  'blog.word-to-pdf-without-losing-formatting.s2.p1': 'The conversion runs in your browser, so the document is not uploaded anywhere.',
  'blog.word-to-pdf-without-losing-formatting.s2.o1.1': 'Open the tool and choose your DOCX file (up to 50 MB).',
  'blog.word-to-pdf-without-losing-formatting.s2.o1.2': 'Pick the page size. You can keep the size set in the document or choose another one.',
  'blog.word-to-pdf-without-losing-formatting.s2.o1.3': 'Press Convert. The tool reads the document, lays out the pages and builds the PDF.',
  'blog.word-to-pdf-without-losing-formatting.s2.o1.4': 'Read the notes under the result. If something could not be converted, they tell you what and how many.',
  'blog.word-to-pdf-without-losing-formatting.s2.o1.5': 'Download the PDF and open it before you send it.',
  'blog.word-to-pdf-without-losing-formatting.s3.h': 'What is kept',
  'blog.word-to-pdf-without-losing-formatting.s3.p1': 'The converter reads the content and structure of the document and lays it out again. These parts carry over:',
  'blog.word-to-pdf-without-losing-formatting.s3.l1.1': 'Bold, italic, underlined text and hyperlinks.',
  'blog.word-to-pdf-without-losing-formatting.s3.l1.2': 'Headings and paragraph alignment.',
  'blog.word-to-pdf-without-losing-formatting.s3.l1.3': 'Bullet and numbered lists.',
  'blog.word-to-pdf-without-losing-formatting.s3.l1.4': 'Tables.',
  'blog.word-to-pdf-without-losing-formatting.s3.l1.5': 'Pictures in JPEG and PNG format.',
  'blog.word-to-pdf-without-losing-formatting.s3.l1.6': 'Line breaks, page breaks and the page orientation.',
  'blog.word-to-pdf-without-losing-formatting.s3.p2': 'Because the text stays real text, you can select, search and copy it in the PDF.',
  'blog.word-to-pdf-without-losing-formatting.s4.h': 'What is approximated or left out',
  'blog.word-to-pdf-without-losing-formatting.s4.p1': 'Be realistic about these differences, and check them in the result:',
  'blog.word-to-pdf-without-losing-formatting.s4.l1.1': 'Fonts. The original fonts are replaced by Noto Sans, so line breaks and page breaks will fall in different places than in Word.',
  'blog.word-to-pdf-without-losing-formatting.s4.l1.2': 'Layout features such as columns and text that wraps around a picture are not reproduced.',
  'blog.word-to-pdf-without-losing-formatting.s4.l1.3': 'Headers, footers and footnotes are not included.',
  'blog.word-to-pdf-without-losing-formatting.s4.l1.4': 'Text boxes, equations, charts, shapes and pictures in formats other than JPEG and PNG are skipped.',
  'blog.word-to-pdf-without-losing-formatting.s4.l1.5': 'Scripts that Noto Sans does not cover, such as Arabic, Hebrew, Thai, Chinese, Japanese and Korean, appear as question marks. The tool tells you how many characters were affected.',
  'blog.word-to-pdf-without-losing-formatting.s4.p2': 'The tool counts what it skipped and says so under the result, so you are never left guessing why a table or a picture is missing.',
  'blog.word-to-pdf-without-losing-formatting.s5.h': 'Prepare the document for a cleaner PDF',
  'blog.word-to-pdf-without-losing-formatting.s5.p1': 'A few minutes of preparation in Word makes the PDF better:',
  'blog.word-to-pdf-without-losing-formatting.s5.o1.1': 'Use real headings and lists instead of manual spacing and typed bullets. Structure converts well; hand-drawn spacing does not.',
  'blog.word-to-pdf-without-losing-formatting.s5.o1.2': 'Put pictures in line with the text, and save them as JPEG or PNG. Floating pictures and other formats may not carry over.',
  'blog.word-to-pdf-without-losing-formatting.s5.o1.3': 'Move important information out of headers, footers and text boxes into the main text.',
  'blog.word-to-pdf-without-losing-formatting.s5.o1.4': 'Replace special equations or charts with a picture saved as PNG or JPG.',
  'blog.word-to-pdf-without-losing-formatting.s5.o1.5': 'Save the file in the current DOCX format. If your file is an old .doc, open it in Word and use Save As, then choose DOCX.',
  'blog.word-to-pdf-without-losing-formatting.s5.n1': 'Tip: convert a short test first. If the first page looks right, the rest almost always will too.',
  'blog.word-to-pdf-without-losing-formatting.s6.h': 'Page size: keep the document’s or choose one',
  'blog.word-to-pdf-without-losing-formatting.s6.p1': 'By default the PDF uses the page size stored in the document, such as A4 or Letter. If you are sending the file to a country or office that prints on the other standard, choose it explicitly. Remember that a different page size also changes where lines and pages break.',
  'blog.word-to-pdf-without-losing-formatting.s7.h': 'After the PDF exists',
  'blog.word-to-pdf-without-losing-formatting.s7.l1.1': 'If it is too large, run <tool_compress_pdf>Compress PDF</tool_compress_pdf>. Our guide to <post_compress-pdf-without-losing-quality>compressing a PDF without losing quality</post_compress-pdf-without-losing-quality> explains the options.',
  'blog.word-to-pdf-without-losing-formatting.s7.l1.2': 'To combine several converted documents, use <tool_merge_pdf>Merge PDF</tool_merge_pdf>; see <post_how-to-merge-pdf-files>how to merge PDF files</post_how-to-merge-pdf-files>.',
  'blog.word-to-pdf-without-losing-formatting.s7.l1.3': 'To restrict who can open the file, add a password with <tool_protect_pdf>Protect PDF</tool_protect_pdf>. Our guide to <post_password-protect-and-unlock-a-pdf>protecting and unlocking a PDF</post_password-protect-and-unlock-a-pdf> covers it in detail.',
  'blog.word-to-pdf-without-losing-formatting.s7.p1': 'The same approach works for other Office files. <tool_excel_to_pdf>Excel to PDF</tool_excel_to_pdf> turns workbooks into tables, and <tool_powerpoint_to_pdf>PowerPoint to PDF</tool_powerpoint_to_pdf> gives one page per slide. <tool_html_to_pdf>HTML to PDF</tool_html_to_pdf> handles web content you have saved as a file.',
  'blog.word-to-pdf-without-losing-formatting.s8.h': 'Troubleshooting',
  'blog.word-to-pdf-without-losing-formatting.s8.l1.1': 'The tool says the file is not a valid document: check that it is really a DOCX and not an old .doc renamed, and that it is not password-protected.',
  'blog.word-to-pdf-without-losing-formatting.s8.l1.2': 'Pages break in different places than in Word: that is expected, because the fonts differ. Adjust the page size or spacing in Word and convert again.',
  'blog.word-to-pdf-without-losing-formatting.s8.l1.3': 'A picture is missing: it was probably in an unsupported format or inside a text box. Re-insert it in line with the text as a JPEG or PNG.',
  'blog.word-to-pdf-without-losing-formatting.s8.l1.4': 'Text shows question marks: the characters are in a script the tool does not support yet.',
  'blog.word-to-pdf-without-losing-formatting.faq.h': 'Frequently asked questions',
  'blog.word-to-pdf-without-losing-formatting.faq.1.q': 'Will the PDF look exactly like my Word document?',
  'blog.word-to-pdf-without-losing-formatting.faq.1.a': 'Not exactly. The tool does not use Microsoft Word, so fonts, spacing and page breaks differ. It reproduces the content and structure, not the exact layout, so check the result before you send it.',
  'blog.word-to-pdf-without-losing-formatting.faq.2.q': 'Can I convert an old .doc file?',
  'blog.word-to-pdf-without-losing-formatting.faq.2.a': 'Not directly. Open it in Word, save it as a DOCX file and convert that.',
  'blog.word-to-pdf-without-losing-formatting.faq.3.q': 'Is my document uploaded to a server?',
  'blog.word-to-pdf-without-losing-formatting.faq.3.a': 'No. The conversion runs in your browser tab and the file stays on your device.',
  'blog.word-to-pdf-without-losing-formatting.faq.4.q': 'Can I convert a password-protected document?',
  'blog.word-to-pdf-without-losing-formatting.faq.4.a': 'No. Remove the protection in Word first, then convert the document.',
  'blog.word-to-pdf-without-losing-formatting.faq.5.q': 'Why is the text in my PDF a different font?',
  'blog.word-to-pdf-without-losing-formatting.faq.5.a': 'The original fonts are replaced by Noto Sans so that the PDF can be built in the browser. This is also why line and page breaks can move.',
  'blog.word-to-pdf-without-losing-formatting.cta.h': 'Convert a document now',
  'blog.word-to-pdf-without-losing-formatting.cta.p': 'Open <tool_word_to_pdf>Word to PDF</tool_word_to_pdf>, or browse all of the <all_pdf>PDF tools</all_pdf>.',
} as const;
